
  /* Banco de perguntas: cada registro é independente e fácil de ampliar. */
  // Busca sem acentos e sem diferença entre maiúsculas/minúsculas. Essa função
  // inicializa várias áreas do portal; sem ela, o restante do JavaScript parava.
  function normalizeText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
  const CATEGORIES = [
    {name:'Abertura, alteração e encerramento de empresas',icon:'🏢',short:'Formalização e mudanças societárias'},
    {name:'Regimes tributários',icon:'🧭',short:'MEI, Simples, Presumido e Real'},
    {name:'Impostos',icon:'🧾',short:'ICMS, ISS, PIS/Cofins, IRPJ, CSLL, IPI e INSS'},
    {name:'Notas fiscais e obrigações acessórias',icon:'📑',short:'NF-e, SPED, ECD, ECF, DCTF e eSocial'},
    {name:'Contabilidade geral',icon:'📊',short:'Balanço, DRE, caixa e conciliação'},
    {name:'Departamento pessoal',icon:'👥',short:'Folha, férias, 13º, rescisão e FGTS'},
    {name:'Imposto de Renda',icon:'💰',short:'Pessoa física e pessoa jurídica'},
    {name:'Planejamento tributário',icon:'🧠',short:'Eficiência dentro da lei'},
    {name:'Regularização fiscal',icon:'🛠️',short:'Pendências, parcelamentos e malha fina'},
    {name:'Reforma Tributária',icon:'🔄',short:'IBS, CBS, IS e preparação para a transição',featured:true},
    {name:'EFD-Reinf',icon:'🧮',short:'Retenções, eventos, fechamento e DCTFWeb'},
    {name:'DIFAL',icon:'🚚',short:'Diferencial de ICMS e operações interestaduais'},
    {name:'Todos os impostos',icon:'📚',short:'Guias por tributo, regime e obrigação'},
    {name:'Mapa de crédito',icon:'🗺️',short:'Documentos, condições e vedações de créditos'}
  ];
  const Q = [];
  function add(category, items){ items.forEach(([question,quick,detail,example,legal,tags,errors,tip])=>Q.push({category,question,resposta:quick,detalhada:detail,exemplo:example,baseLegal:legal,tags,erros:errors,tip,relacionadas:[]})); }
  add(CATEGORIES[0].name,[
    ['Quais são os passos básicos para abrir uma empresa?','Defina atividade, endereço, natureza jurídica e regime; depois faça registro, inscrições e licenças que se aplicam.','A abertura costuma envolver consulta de viabilidade, ato constitutivo, registro na Junta Comercial ou cartório, CNPJ e inscrições/licenças conforme atividade e município. A ordem e integração variam por estado.','Uma loja pode precisar de viabilidade do endereço, registro, CNPJ, inscrição estadual, alvará ou licenças específicas antes de iniciar.','Código Civil; Lei 8.934/1994; normas do DREI e legislação local.','Estudante, Simples Nacional','Começar a vender antes de conferir licenças; escolher CNAE que não representa a atividade.','Faça o desenho da operação antes de preencher o cadastro: atividade, endereço e sócios afetam tributação e licenças.'],
    ['Como escolher a natureza jurídica da empresa?','A natureza jurídica depende de quem participa, da responsabilidade e da estrutura pretendida.','Compare empresário individual, sociedade limitada unipessoal e sociedade limitada, entre outras formas. A escolha não define sozinha o regime tributário. Leve em conta responsabilidade, governança, sucessão e regras profissionais.','Uma pessoa que abre uma consultoria pode avaliar uma limitada unipessoal; a responsabilidade e a estrutura devem ser analisadas com contrato e atividade em mãos.','Código Civil, especialmente regras das sociedades; Lei 8.934/1994.','Estudante, Lucro Presumido, Lucro Real','Achar que “MEI” é natureza jurídica; usar contrato padrão sem revisar responsabilidades.','Separe os conceitos: porte, natureza jurídica e regime tributário são escolhas diferentes.'],
    ['Posso alterar o endereço ou atividade da empresa?','Em geral, sim, mas a alteração precisa ser registrada e pode exigir nova viabilidade, licenças e atualização cadastral.','Confirme se o novo endereço comporta a atividade, atualize o ato societário/cadastro na Junta e os registros federal, estadual e municipal integrados. A operação no novo local pode depender de licença.','Uma empresa que troca de município deve revisar inscrição municipal, ISS e cadastro fiscal, além do endereço na Receita.','Código Civil; Lei 8.934/1994; normas do DREI e legislação municipal/estadual.','Simples Nacional, Lucro Presumido, Lucro Real','Mudar primeiro e atualizar depois; esquecer cadastro de NF e licenças sanitárias ou ambientais.','Planeje a data da mudança com o contador e com a prefeitura/SEFAZ antes de emitir documentos no novo endereço.'],
    ['Como incluir ou retirar um sócio?','É preciso formalizar a alteração societária, apurar efeitos econômicos e atualizar os cadastros da empresa.','A alteração exige observar o contrato, consentimentos, cessão de quotas, capital, responsabilidade por obrigações e eventuais efeitos fiscais. O registro e atualização cadastral devem ser feitos pelos canais oficiais.','Se um sócio vende quotas por valor diferente do custo, pode haver ganho de capital para a pessoa física; avalie a operação antes da assinatura.','Código Civil; normas do DREI; legislação do Imposto de Renda sobre ganho de capital.','Lucro Real, Lucro Presumido, Estudante','Tratar saída societária como simples mudança cadastral; não documentar preço e pagamento.','Faça um balanço de corte e formalize a negociação com documentos e comprovantes.'],
    ['Como encerrar uma empresa sem movimento?','Empresa sem faturamento não está automaticamente encerrada; formalize a baixa e entregue obrigações pendentes.','A baixa costuma envolver distrato ou ato de extinção, registro e pedidos nos cadastros integrados. Obrigações acessórias e débitos anteriores podem continuar exigíveis mesmo após a baixa, conforme a lei.','Uma empresa parada por meses pode ainda ter declarações sem movimento a entregar, conforme seu regime e obrigação.','Código Civil; Lei 8.934/1994; LC 123/2006, quando aplicável; regras cadastrais da RFB.','MEI, Simples Nacional','Parar de pagar DAS e presumir que o CNPJ baixou; ignorar declarações finais.','Peça uma relação de pendências fiscais e contábeis antes do protocolo de baixa.'],
    ['Posso abrir empresa em endereço residencial?','Depende da atividade, do zoneamento, das regras municipais e do contrato do imóvel.','Atividades sem atendimento, estoque ou impacto urbano podem ter tratamento diferente de operação com circulação de pessoas, ruído, risco ou produção. Consulte a viabilidade do endereço e as regras de condomínio e prefeitura.','Uma consultoria remota pode ter caminho distinto de uma cozinha que produz alimentos em casa, que exige análise sanitária e de uso do solo.','Lei 11.598/2007; legislação municipal de uso e ocupação do solo e licenciamento.','MEI, Simples Nacional','Usar endereço residencial sem verificar zoneamento ou licença; ignorar condomínio e contrato de locação.','Consulte a viabilidade antes de registrar o endereço no CNPJ.']
  ]);
  add(CATEGORIES[1].name,[
    ['Como saber se posso ser MEI?','Confira atividade permitida, limite de receita, participação em outras empresas e regras para empregados.','O MEI é uma modalidade simplificada com condições legais específicas. A lista de ocupações permitidas e limites devem ser conferidos no Portal do Empreendedor; propostas de mudança de limite não alteram a lei antes de aprovação e vigência.','Uma pessoa com atividade não permitida não deve escolher um CNAE parecido só para entrar no MEI; pode haver desenquadramento e cobrança retroativa.','LC 123/2006, arts. 18-A e seguintes; Resolução CGSN 140/2018 e lista vigente.','MEI','Confundir MEI com microempresa; incluir sócio ou atividade vedada.','Use a ocupação real, não apenas a descrição mais conveniente no sistema.'],
    ['O que define o valor do DAS do MEI?','O DAS soma contribuição previdenciária e, conforme a atividade, parcela fixa de ISS e/ou ICMS.','No MEI comum, a parte previdenciária corresponde a percentual do salário mínimo; o transportador autônomo de cargas tem regra própria. Os valores mudam com o salário mínimo e devem ser gerados no PGMEI.','Em 2026, a Receita informou salário mínimo de R$ 1.621: 5% correspondem a R$ 81,05; podem somar-se R$ 5 de ISS e/ou R$ 1 de ICMS conforme atividade.','LC 123/2006; Resolução CGSN 140/2018; valores oficiais do PGMEI para o ano.','MEI','Pagar valor copiado de ano anterior; deixar DAS vencer por achar que sem faturamento não há cobrança.','Gere a guia no PGMEI; não pague boleto recebido por mensagem sem conferir origem.'],
    ['Como funciona o Simples Nacional?','É um regime simplificado que reúne tributos em documento de arrecadação único, com cálculo conforme atividade, receita e regras legais.','A opção depende de limites, vedações e regularidade. O cálculo usa receita acumulada, anexo, faixa, alíquota nominal e parcela a deduzir; receitas precisam ser segregadas corretamente no PGDAS-D.','Duas empresas com a mesma receita podem ter alíquotas efetivas diferentes por atividade, folha, retenções e segregação.','LC 123/2006; Resolução CGSN 140/2018.','MEI, Simples Nacional','Tratar a alíquota inicial como taxa fixa; esquecer sublimites ou receitas sujeitas a tratamento específico.','Revise o cadastro de produtos/serviços e a segregação antes de transmitir cada apuração.'],
    ['Quando o Lucro Presumido pode ser avaliado?','Pode ser avaliado por empresas dentro dos limites legais e sem vedação, comparando a presunção com a margem real.','Nesse regime, bases de IRPJ e CSLL são estimadas por percentuais legais aplicados à receita, com particularidades por atividade. PIS/Cofins e tributos locais também entram na conta.','Uma empresa de serviços com margem elevada pode encontrar cenário diferente de uma operação de margem estreita; faturamento sozinho não decide.','Lei 9.718/1998; Leis 9.249/1995 e 9.430/1996; legislação de PIS/Cofins.','Lucro Presumido','Comparar só IRPJ/CSLL e ignorar PIS/Cofins, ISS, folha, retenções e créditos.','Simule o ano inteiro e considere sazonalidade, não apenas um mês bom.'],
    ['Quando o Lucro Real é obrigatório ou pode valer a pena?','Algumas pessoas jurídicas estão legalmente obrigadas; outras podem optar quando a apuração baseada no lucro contábil faz sentido.','No Lucro Real, IRPJ e CSLL partem do lucro líquido ajustado por adições, exclusões e compensações permitidas. A qualidade da contabilidade e do controle de estoque/despesas é central.','Com margem baixa e controles robustos, uma empresa pode estudar o Real; se os registros forem frágeis, a apuração vira risco.','Lei 9.718/1998; Decreto 9.580/2018; Leis 9.430/1996 e 9.249/1995.','Lucro Real','Achar que prejuízo contábil elimina qualquer imposto; lançar despesas sem suporte.','Antes de optar, valide capacidade de fechar balancetes e manter documentação ao longo do ano.'],
    ['Posso mudar de regime tributário durante o ano?','Em regra, a opção produz efeitos por período e não pode ser trocada livremente no meio do ano; há exceções legais.','O momento de opção depende do regime e do evento: início de atividade, exclusão, impedimento ou outra hipótese. A mudança pode exigir planejamento de estoque, créditos, folha e obrigações.','Uma empresa que cresceu acima do limite não deve aguardar o fim do exercício sem verificar data e efeitos do desenquadramento.','LC 123/2006; Lei 9.718/1998; normas da Receita e do CGSN.','Simples Nacional, Lucro Real','Assumir que uma opção feita em janeiro pode ser cancelada quando convém.','Confira o prazo e o efeito da opção no portal oficial antes de transmitir pedido.']
  ]);
  add(CATEGORIES[2].name,[
    ['Como identificar se uma venda tem ICMS ou ISS?','A natureza da operação, a lista de serviços, a circulação de mercadoria e regras específicas indicam o tributo e o ente competente.','ICMS incide sobre operações previstas na Constituição e na LC 87/1996; ISS sobre serviços listados na LC 116/2003, respeitadas exceções. Operações mistas e casos especiais pedem análise do contrato e da legislação local.','Uma instalação com fornecimento de material pode ter tratamento diferente conforme o serviço listado e a operação; não decida apenas pelo nome da nota.','CF/1988, arts. 155 e 156; LC 87/1996; LC 116/2003.','Simples Nacional, Lucro Presumido, Lucro Real','Classificar pelo CNAE sem ler o que foi efetivamente vendido.','Descreva claramente o objeto, materiais, local e responsabilidade em contrato e documento fiscal.'],
    ['Como funcionam PIS e Cofins?','São contribuições federais cuja incidência depende do regime, da atividade e de regras cumulativas, não cumulativas ou monofásicas.','A apuração precisa considerar base, créditos admitidos, produtos, retenções e regimes específicos. A partir da transição da reforma, a CBS substitui gradualmente PIS/Cofins, conforme legislação e cronograma.','Uma revenda de produto sujeito a tributação monofásica não deve copiar o cálculo de uma receita comum sem verificar NCM e cadeia.','Leis 9.718/1998, 10.637/2002 e 10.833/2003; LC 214/2025.','Lucro Real, Lucro Presumido','Tomar crédito sem documento ou previsão; aplicar monofásico só pela descrição comercial.','Valide NCM, CST e natureza da receita em conjunto; revise cadastro na origem.'],
    ['Quando há retenção de ISS na nota de serviço?','A retenção depende da LC 116/2003, do município competente, do serviço e da condição do tomador.','Confira local de incidência, responsabilidade atribuída ao tomador e regras municipais. O destaque ou retenção incorreta pode gerar cobrança duplicada ou falta de recolhimento.','Uma prestadora em um município atende tomador em outro: local de incidência e retenção precisam ser avaliados pelo item da lista e pela legislação local.','LC 116/2003, especialmente arts. 3º e 6º; legislação municipal.','Simples Nacional, Lucro Presumido','Reter automaticamente em toda nota; esquecer de informar retenção na apuração.','Guarde o comprovante de retenção e concilie com a nota e a apuração mensal.'],
    ['Como calcular IRPJ e CSLL da empresa?','A forma depende do regime: lucro real, presumido ou arbitrado, com bases e ajustes definidos em lei.','No Real, parte-se do lucro líquido com ajustes fiscais; no Presumido, aplicam-se percentuais de presunção por atividade. No Simples, há recolhimento no DAS segundo regras próprias.','Uma prestadora no Presumido não usa automaticamente o percentual aplicável a comércio; a atividade efetiva e a receita precisam ser classificadas.','Decreto 9.580/2018; Leis 9.249/1995 e 9.430/1996; LC 123/2006.','Lucro Presumido, Lucro Real','Calcular tudo sobre faturamento sem separar receitas; ignorar adicional ou regras específicas.','Faça conciliação entre receita fiscal, contabilidade e declarações antes de fechar o período.'],
    ['Como saber o IPI de um produto?','Consulte a TIPI pela classificação fiscal correta do produto e examine notas complementares e regras de incidência.','O NCM sozinho exige descrição técnica compatível. O IPI depende do produto, operação, industrialização/equiparação e benefícios aplicáveis. A reforma prevê redução a zero em regra, com exceções para preservação de diferencial competitivo da Zona Franca.','Produto com nome comercial parecido pode ter NCM e tratamento distintos por composição, uso ou apresentação.','CF/1988, art. 153, IV; RIPI (Decreto 7.212/2010); TIPI vigente; LC 214/2025.','Lucro Real, Lucro Presumido','Escolher NCM por busca na internet sem ficha técnica; ignorar Ex da TIPI.','Mantenha laudo/ficha do produto, composição e justificativa da classificação.'],
    ['Como funciona o INSS sobre pró-labore?','O sócio remunerado pelo trabalho pode ter contribuição previdenciária retida; a empresa também pode ter encargo patronal conforme o caso.','A contribuição do contribuinte individual tem alíquota e limites por competência. Mais de uma fonte pagadora, teto, atividade e regime da empresa alteram o tratamento. A folha precisa ser informada corretamente.','Se o sócio recebe pró-labore de duas empresas, a soma das bases pode afetar o desconto até o teto previdenciário.','Lei 8.212/1991; Decreto 3.048/1999; normas previdenciárias vigentes.','Simples Nacional, Lucro Real','Tratar distribuição de lucros como pró-labore sem documentação; ignorar contribuição patronal.','Separe remuneração pelo trabalho e distribuição de lucro, com contabilidade e ata/documentação.']
  ]);
  add(CATEGORIES[3].name,[
    ['Quando preciso emitir NF-e, NFC-e ou NFS-e?','O documento depende do tipo de operação, da atividade, do estado/município e do perfil do contribuinte.','NF-e é usada em operações com mercadorias em situações previstas; NFC-e atende venda ao consumidor em regras estaduais; NFS-e documenta serviços conforme legislação municipal e padrão aplicável. MEI e pessoa física têm regras próprias.','Uma venda de mercadoria para outra empresa e um serviço prestado a consumidor não devem usar o mesmo modelo sem checar a regra local.','Ajuste SINIEF 07/2005 (NF-e); Ajuste SINIEF 19/2016 (NFC-e); LC 116/2003 e regras da NFS-e.','MEI, Simples Nacional','Emitir modelo errado; esquecer inscrição, credenciamento ou contingência autorizada.','Configure série, natureza, CFOP, NCM/serviço e destinatário com validação prévia.'],
    ['O que é SPED Fiscal (EFD ICMS/IPI)?','É uma escrituração digital de documentos e apurações de ICMS/IPI para contribuintes obrigados.','A EFD reúne registros de documentos, itens, inventário e apuração conforme perfil, UF e regras vigentes. A obrigação pode variar por contribuinte e estado; valide dispensa e leiaute atualizado.','Uma nota com CFOP/CST incorretos pode contaminar registros e gerar divergência entre escrituração, documento e apuração.','Ajuste SINIEF 02/2009; Guia Prático da EFD ICMS/IPI e legislação estadual.','Lucro Presumido, Lucro Real','Achar que importar XML garante escrituração correta; ignorar cadastro de produtos e inventário.','Concilie XML, entradas/saídas, estoque e apuração antes de transmitir.'],
    ['O que são ECD e ECF?','ECD substitui livros contábeis em formato digital quando exigida; ECF informa dados fiscais e apuração de IRPJ/CSLL nas hipóteses aplicáveis.','São escriturações distintas e têm regras de obrigatoriedade, prazo, leiaute e cruzamentos. Há dispensas e exceções conforme porte e regime; confirme o manual do ano-calendário.','Diferenças entre saldo final da ECD e saldos iniciais da ECF podem gerar intimação ou necessidade de retificação.','IN RFB 2.003/2021 (ECD); IN RFB 2.004/2021 (ECF), com alterações e manuais vigentes.','Lucro Real, Lucro Presumido','Transmitir sem validar plano referencial; esquecer recuperação da ECD anterior.','Faça validação no PGE, confira recibos e mantenha cópia da versão transmitida.'],
    ['O que mudou na DCTF e na DCTFWeb?','A obrigação declaratória federal foi sendo reorganizada; a DCTFWeb e o MIT devem ser conferidos conforme tributos e período.','A forma de declarar débitos varia por competência, contribuinte e cronograma de implantação. Consulte o manual e as normas atuais antes de assumir que uma declaração substitui outra.','Uma guia paga não prova que o débito foi declarado corretamente; compare apuração, declaração e DARF.','IN RFB 2.005/2021 e atos posteriores; manuais oficiais da DCTFWeb e MIT.','Lucro Real, Lucro Presumido','Confundir transmissão de eSocial/EFD-Reinf com encerramento da DCTFWeb; esquecer MIT quando aplicável.','Use checklist de origem do débito, fechamento, transmissão e pagamento.'],
    ['Como corrigir uma nota fiscal emitida com erro?','Use o evento ou procedimento permitido para o tipo de erro; carta de correção não altera qualquer campo.','Cancelamento, substituição, complementação ou carta de correção dependem do modelo, prazo, UF/município e natureza do erro. Em alguns casos, é preciso documento de entrada/devolução ou nota complementar.','Se o erro altera valor, imposto, destinatário ou data, a carta de correção pode ser insuficiente; avalie a regra antes de emitir outro documento.','Ajustes SINIEF e normas estaduais; LC 116/2003 e regulamentos municipais para NFS-e.','MEI, Simples Nacional','Cancelar fora do prazo sem autorização; emitir segunda nota sem referenciar a primeira.','Guarde XML, protocolo e justificativa do procedimento adotado.'],
    ['O que é eSocial e quem informa eventos?','É o sistema que recebe informações trabalhistas, previdenciárias e fiscais de empregadores, conforme perfil e obrigação.','Eventos cadastrais, não periódicos e periódicos alimentam obrigações e apurações. Prazos mudam por evento e situação; envio precisa refletir documentos e folha reais.','Uma admissão informada depois do início do trabalho pode gerar inconsistência e penalidade; organize o envio antes do primeiro dia.','Decreto 8.373/2014; CLT; Lei 8.212/1991; Manual de Orientação do eSocial vigente.','Simples Nacional, Lucro Real','Achar que folha fechada corrige cadastro incompleto; enviar evento com data divergente do contrato.','Mantenha calendário de eventos e valide retornos e recibos, não apenas o envio.']
  ]);
  add(CATEGORIES[4].name,[
    ['O que mostra o balanço patrimonial?','Mostra ativos, passivos e patrimônio líquido em uma data, com saldos classificados conforme normas contábeis.','É uma fotografia da posição patrimonial. Deve refletir caixa, clientes, estoques, imobilizado, dívidas e patrimônio líquido após conciliações e ajustes.','Se o caixa contábil é R$ 8 mil e o extrato indica R$ 6 mil, a diferença precisa ser conciliada, não escondida em uma conta genérica.','Lei 6.404/1976, arts. 176 e seguintes, quando aplicável; NBC TG Estrutura Conceitual e normas pertinentes.','Estudante, Lucro Real','Confundir saldo bancário com lucro; apresentar contas sem suporte.','Feche cada conta com documentação e explicação de saldo.'],
    ['Para que serve a DRE?','A Demonstração do Resultado mostra receitas, custos, despesas e resultado de um período pelo regime de competência.','A DRE explica como o resultado se formou, incluindo deduções, custos, despesas e tributos conforme apresentação aplicável. Não é um extrato de caixa.','Venda faturada a prazo pode entrar na DRE antes de o cliente pagar; o caixa só muda quando houver recebimento.','Lei 6.404/1976, art. 187, quando aplicável; NBC TG 26 e normas pertinentes.','Estudante, Lucro Real','Lançar entrada de empréstimo como receita; misturar gastos pessoais e da empresa.','Analise margem e variação por mês junto com o fluxo de caixa.'],
    ['Qual a diferença entre lucro e caixa?','Lucro é resultado econômico pelo regime de competência; caixa é dinheiro disponível em determinado momento.','Prazos de recebimento e pagamento, estoque, investimento e empréstimos explicam por que uma empresa lucrativa pode ficar sem caixa.','A empresa vende R$ 50 mil a prazo e paga fornecedores à vista; o resultado pode ser positivo enquanto o saldo bancário aperta.','Código Civil; Lei 6.404/1976 e normas contábeis aplicáveis.','Estudante, Simples Nacional','Olhar apenas saldo bancário para decidir distribuição de lucros.','Projete entradas e saídas por data e acompanhe inadimplência.'],
    ['Como fazer conciliação bancária?','Compare cada lançamento do extrato com os registros contábeis e explique diferenças pendentes.','Concilie conta a conta, identifique tarifas, transferências em trânsito, recebimentos e pagamentos sem baixa. Diferenças antigas devem ser investigadas, não carregadas indefinidamente.','Um recebimento via cartão pode aparecer líquido no banco e bruto na venda; taxas precisam ser separadas.','NBC TG Estrutura Conceitual; normas contábeis aplicáveis à entidade.','Lucro Real, Estudante','Lançar valor líquido como receita; ignorar tarifas ou transferências entre contas.','Faça a conciliação mensal e guarde extrato e relatório de adquirente.'],
    ['Como calcular depreciação?','A depreciação distribui o valor depreciável de um ativo ao longo de sua vida útil estimada.','Identifique custo, valor residual, vida útil e método que represente o consumo econômico. A taxa fiscal pode divergir da contábil e exigir controle de diferenças.','Máquina de R$ 60 mil com vida útil contábil estimada de 5 anos e valor residual zero: linha reta indicaria R$ 12 mil ao ano, se premissas forem adequadas.','NBC TG 27; Lei 6.404/1976; regras fiscais do Decreto 9.580/2018.','Lucro Real, Estudante','Aplicar taxa fiscal automaticamente na contabilidade; depreciar item que não está disponível para uso sem análise.','Mantenha ficha de imobilizado, data de uso e justificativa da vida útil.'],
    ['O que é regime de competência?','Receitas e despesas são reconhecidas quando ocorrem economicamente, não necessariamente quando o dinheiro entra ou sai.','O regime de competência permite medir resultado do período e obrigações a pagar/receber. O fluxo de caixa é controle complementar.','Conta de energia de dezembro paga em janeiro é reconhecida no período de consumo, conforme competência.','Código Civil, art. 1.179; Lei 6.404/1976; NBC TG Estrutura Conceitual.','Estudante, Lucro Real','Reconhecer toda despesa só quando paga; omitir contas a receber e provisões.','Registre documento, período de competência e data de pagamento separadamente.']
  ]);
  add(CATEGORIES[5].name,[
    ['Como é calculado o salário de férias?','Em regra, as férias incluem a remuneração devida e o adicional constitucional de um terço, observados períodos e regras da CLT.','O cálculo depende de salário, médias variáveis, faltas que afetem o direito, períodos aquisitivo/concessivo e eventual abono. O pagamento deve respeitar o prazo legal.','Para salário fixo de R$ 2.400, a remuneração bruta de férias sem variáveis seria R$ 2.400 + 1/3 (R$ 800) = R$ 3.200, antes de descontos.','Constituição Federal, art. 7º, XVII; CLT, arts. 129 a 145.','Estudante, Simples Nacional','Esquecer médias de comissão ou pagar fora do prazo; confundir abono com venda automática de dias.','Programe férias e fechamento da folha com antecedência e confira períodos.'],
    ['Como funciona o 13º salário?','O 13º é calculado conforme meses trabalhados no ano, com fração mínima de dias prevista em lei e integração de parcelas aplicáveis.','A remuneração e médias variáveis entram conforme legislação. A primeira e segunda parcelas têm regras próprias de pagamento e descontos. Mudanças de remuneração exigem recálculo.','Quem trabalhou 6 meses que contam para o cálculo pode ter direito proporcional a 6/12 da remuneração, sujeito à apuração correta.','Lei 4.090/1962; Lei 4.749/1965; Decreto 57.155/1965.','Estudante, Simples Nacional','Contar mês sem verificar dias trabalhados; esquecer comissão e afastamentos.','Mantenha médias variáveis conciliadas com eventos da folha.'],
    ['O que deve ser pago na rescisão?','As verbas dependem do motivo do desligamento, do contrato e do tempo trabalhado; não existe cálculo único para toda rescisão.','Podem existir saldo de salário, aviso prévio, férias, 13º proporcional, depósitos e indenizações, conforme a modalidade. Prazos e documentação precisam ser conferidos na CLT e regras vigentes.','Pedido de demissão e dispensa sem justa causa têm componentes diferentes; simule somente depois de confirmar motivo e datas.','CLT, arts. 477 e seguintes; Lei 8.036/1990; normas coletivas aplicáveis.','Estudante, Simples Nacional','Usar modelo de rescisão de outro caso; errar data de aviso ou projeção.','Revise convenção coletiva, recibos, ponto e eventos enviados antes de fechar.'],
    ['Como funciona o FGTS?','Empregadores depositam FGTS nas contas vinculadas dos trabalhadores conforme vínculo e regras legais.','A incidência e o recolhimento variam por tipo de trabalhador, remuneração e evento. O FGTS Digital centraliza operações para grupos obrigados; confira guias, bases e prazos.','Uma verba remuneratória pode compor a base do FGTS; classifique cada rubrica segundo a legislação.','Lei 8.036/1990; Decreto 99.684/1990; Manual do FGTS Digital vigente.','Estudante, Simples Nacional','Confundir desconto do trabalhador com depósito patronal; recolher por guia ou competência errada.','Concilie folha, eSocial, FGTS Digital e comprovante de pagamento.'],
    ['Hora extra entra no cálculo de férias e 13º?','Parcelas habituais e variáveis podem repercutir, conforme natureza, frequência e regras trabalhistas.','A integração depende de rubrica, habitualidade e critérios legais ou coletivos. Registre jornada e eventos corretamente; não adote média improvisada.','Comissões e horas extras recorrentes podem alterar médias de férias e 13º; o cálculo deve considerar período aplicável.','CLT; Constituição Federal; súmulas e normas coletivas vigentes, quando pertinentes.','Estudante','Pagar variável por fora; cadastrar rubrica como indenizatória sem base jurídica.','Revise rubricas e convenção coletiva com profissional de DP/jurídico.'],
    ['O que é pró-labore e quem recebe?','Pró-labore remunera o trabalho do sócio; distribuição de lucro remunera o capital e depende de lucro apurado e documentação.','Sócio que trabalha pode ter retirada registrada como pró-labore e incidências previdenciárias. Lucros distribuídos precisam de base contábil e observância das regras tributárias.','Se a empresa transfere valores mensais ao sócio sem classificação, pode haver risco de requalificação e divergência contábil.','Lei 8.212/1991; Código Civil; legislação do IR e normas previdenciárias.','Simples Nacional, Lucro Presumido','Chamar toda retirada de lucro; distribuir sem apuração ou deixar pró-labore incompatível com trabalho.','Formalize política de remuneração e registre retiradas com documentos.']
  ]);
  add(CATEGORIES[6].name,[
    ['Quem precisa entregar a declaração de IRPF?','A obrigatoriedade muda por exercício e depende de critérios publicados pela Receita Federal.','Rendimentos, bens, operações, atividade rural e outras situações podem obrigar. Não use limite de ano anterior: consulte a instrução normativa e página do exercício correspondente.','Uma pessoa isenta de imposto retido pode ainda estar obrigada por patrimônio ou operações, conforme critérios vigentes.','Lei 7.713/1988; Lei 9.250/1995; instrução normativa anual da RFB.','Pessoa Física','Confundir imposto a pagar com obrigação de declarar; declarar em programa de ano errado.','Confira todos os critérios do exercício e guarde informes e recibos.'],
    ['Qual a diferença entre declaração completa e simplificada?','São formas de apurar a base anual; o programa compara deduções legais com desconto simplificado, conforme regras do exercício.','A escolha depende de dependentes, despesas dedutíveis permitidas, previdência, saúde, educação e demais informações. O resultado mais vantajoso varia por pessoa.','Uma pessoa com despesas médicas documentadas pode obter resultado diferente de quem usa apenas desconto simplificado.','Lei 9.250/1995; regras e limites da declaração anual vigentes.','Pessoa Física','Deduzir gasto sem documento ou que não se enquadra; achar que completa sempre é melhor.','Preencha dados completos e compare os dois modelos antes de transmitir.'],
    ['Como declarar renda de aluguel?','Rendimentos de aluguel devem ser informados conforme quem paga, quem recebe e regras de recolhimento aplicáveis.','Aluguel recebido de pessoa física pode exigir apuração mensal via Carnê-Leão; de pessoa jurídica, há informe e retenções. Despesas dedutíveis têm critérios e documentação.','O aluguel recebido por imobiliária continua sendo renda do proprietário; taxas e despesas precisam ser tratadas conforme a regra.','Lei 7.713/1988; Decreto 9.580/2018; normas da RFB.','Pessoa Física','Omitir comissão/imobiliária; deduzir qualquer reforma ou condomínio sem conferir regra.','Concilie contrato, extratos, informes e recolhimentos mensais.'],
    ['Como declarar dependente?','Dependente pode gerar deduções, mas seus rendimentos e bens também podem precisar entrar na declaração.','A relação admitida e as condições dependem da legislação do IRPF do exercício. Incluir dependente exige informar rendimentos, pagamentos e patrimônio pertinentes.','Um filho com estágio remunerado pode ser dependente em certas condições, mas a renda também precisa ser declarada.','Lei 9.250/1995; instrução normativa anual do IRPF.','Pessoa Física','Incluir o dependente em duas declarações; omitir rendimentos ou conta bancária do dependente.','Combine a declaração com o outro responsável e valide a documentação.'],
    ['Como declarar venda de imóvel?','A venda pode gerar ganho de capital; o cálculo considera custo, despesas admitidas, isenções e regras próprias.','Apure o ganho no programa oficial e verifique hipóteses de isenção, como reinvestimento residencial quando os requisitos legais forem atendidos. Regras têm prazos específicos.','Venda por R$ 500 mil não significa ganho de R$ 500 mil: compare com custo fiscal e despesas admitidas.','Lei 7.713/1988; Lei 11.196/2005; Decreto 9.580/2018.','Pessoa Física','Usar preço de mercado como custo; ignorar prazo e condições da isenção.','Apure no GCAP e guarde escritura, comprovantes de aquisição e benfeitorias.'],
    ['Como corrigir declaração de IRPF já enviada?','A retificadora corrige informações, mas não deve mudar o modelo de tributação fora das hipóteses e prazos permitidos.','Use o mesmo exercício e número do recibo, revise todas as fichas e confira se a declaração entrou em malha ou fiscalização. Retificar não elimina tributo devido nem substitui resposta a intimação.','Se esqueceu uma conta bancária, retifique com saldo e rendimentos corretos e guarde os informes.','Lei 9.250/1995; normas da RFB do exercício correspondente.','Pessoa Física','Enviar nova declaração como original; retificar após intimação sem avaliar o procedimento.','Baixe recibo e cópia da declaração transmitida antes de corrigir.']
  ]);
  add(CATEGORIES[7].name,[
    ['O que é planejamento tributário legal?','É organizar operações e escolhas permitidas para cumprir a lei com eficiência, documentação e substância econômica.','Pode envolver regime, estrutura operacional, localização, contratos e créditos, desde que os fatos sejam reais e a forma corresponda à operação. Simulação, omissão ou documento fictício não são planejamento lícito.','Comparar regimes antes do início do ano e ajustar cadastro para refletir atividade verdadeira é planejamento preventivo.','CTN, art. 116, parágrafo único, conforme regulamentação; legislação específica de cada tributo.','Lucro Presumido, Lucro Real','Escolher CNAE fictício; criar operação sem substância apenas para reduzir tributo.','Documente premissas, cenários e razão comercial de cada decisão.'],
    ['Quando vale comparar regimes tributários?','Antes da opção anual, de mudanças relevantes e sempre que receita, margem, folha ou cadeia de créditos mudar.','Compare tributos totais, folha, obrigações, fluxo de caixa, retenções, créditos e risco de desenquadramento. Use projeção por atividade e mês, não só um percentual médio.','Uma empresa com muita folha pode ter cenário diferente de concorrente com mesma receita e equipe menor.','LC 123/2006; Leis 9.718/1998, 9.249/1995 e 9.430/1996.','Simples Nacional, Lucro Presumido, Lucro Real','Escolher pelo menor DAS do mês; ignorar tributos fora do DAS ou obrigações acessórias.','Faça comparação anual e registre as premissas usadas.'],
    ['Posso dividir uma empresa em CNPJs para pagar menos?','A estrutura deve refletir negócios reais; fracionamento artificial para contornar limites pode ser questionado.','Empresas relacionadas, sócios, atividades e receitas podem ter regras de soma ou vedação. A análise exige estrutura societária, operação, autonomia e legislação do regime.','Separar filiais ou atividades sem gestão própria apenas para ficar abaixo de limite pode criar risco fiscal.','LC 123/2006; CTN; Código Civil e legislação aplicável.','Simples Nacional','Abrir CNPJ em nome de familiar sem autonomia real; omitir vínculo entre empresas.','Antes de reorganizar, peça análise escrita dos efeitos societários e tributários.'],
    ['Como a folha pode afetar o Simples Nacional?','Para certas atividades, a relação entre folha e receita pode influenciar o anexo aplicável, conforme regras do fator R.','O fator R compara folha e receita em período definido pela legislação. Classificação da atividade, encargos considerados e dados transmitidos precisam ser corretos.','Uma variação na folha pode mudar o enquadramento de determinada receita, mas não basta aumentar pró-labore sem avaliar custo total e regras.','LC 123/2006, art. 18, §§ 5-J e seguintes; Resolução CGSN 140/2018.','Simples Nacional','Aplicar fator R a toda atividade; usar folha de período incorreto ou sem encargos elegíveis.','Simule mês a mês com dados conciliados entre folha e PGDAS-D.'],
    ['Como revisar créditos tributários sem correr risco?','Mapeie a hipótese legal, documento, vínculo com a atividade, período e prova do crédito antes de compensar.','Crédito tributário não nasce apenas porque houve pagamento ou compra. Cada tributo tem regras próprias de creditamento, vedação, prazo e retificação. Créditos antigos exigem análise de prescrição e documentação.','No Lucro Real, uma despesa pode ser contábil sem necessariamente gerar crédito de PIS/Cofins; examine a lei e precedentes aplicáveis.','Leis 10.637/2002 e 10.833/2003; CTN, arts. 165 e 168; regras de cada tributo.','Lucro Real','Usar planilha genérica de recuperação; compensar antes de validar período e fundamento.','Monte dossiê por tributo, competência, base legal e documento.'],
    ['Como avaliar o impacto da Reforma Tributária no preço?','Mapeie custos, créditos, regime, perfil de cliente e cronograma; não aplique uma alíquota genérica ao preço atual.','A transição altera incidências e créditos gradualmente. O efeito depende da cadeia de compras, possibilidade de crédito, regime e repasse comercial; alíquotas de referência e regulamentação podem evoluir.','Uma indústria que vende para empresas pode ter dinâmica de crédito diferente de um serviço vendido ao consumidor final.','EC 132/2023; LC 214/2025; LC 227/2026 e atos regulamentares.','Simples Nacional, Lucro Real, Lucro Presumido','Repasse integral presumido; ignorar contratos, descontos e créditos de fornecedores.','Faça cenários por produto/serviço e teste preços antes de renegociar contratos.']
  ]);
  add(CATEGORIES[8].name,[
    ['Como consultar débitos federais da empresa?','Consulte a situação fiscal nos portais oficiais, separando débitos em cobrança, declarações pendentes e dívida ativa.','Use e-CAC, Portal do Simples, Regularize/PGFN e sistemas de arrecadação conforme a origem. Compare extratos com declarações, guias e pagamentos; divergência pode ser pagamento não alocado.','Uma guia paga com código ou período errado pode não baixar o débito automaticamente.','CTN; normas da RFB e PGFN; LC 123/2006 quando Simples.','MEI, Simples Nacional','Confiar em print de terceiro; pagar guia sem conferir CNPJ, código e competência.','Baixe relatório de situação fiscal e guarde comprovante bancário e DARF/DAS.'],
    ['Quando uma dívida vai para a dívida ativa?','Após constituição e cobrança administrativa, débitos podem ser inscritos; o fluxo e prazo dependem do órgão e do caso.','A inscrição pode gerar encargos e cobrança judicial ou extrajudicial. Antes de negociar, confira origem, período, responsável e se há causa para impugnação ou revisão.','Um débito municipal de ISS não aparece necessariamente no mesmo portal de um débito federal.','Lei 6.830/1980; CTN; Lei 13.988/2020; normas do ente credor.','Lucro Presumido, MEI','Ignorar notificação; confundir inscrição em dívida ativa com baixa automática após pedido de parcelamento.','Consulte o ente credor e leia a situação da inscrição, inclusive garantias e protesto.'],
    ['Como funciona parcelamento tributário?','O parcelamento segue modalidade, entrada, quantidade de parcelas e condições definidas em lei ou edital.','A adesão pode confessar o débito e interromper prazos; parcelas em atraso podem rescindir o acordo. Regras e benefícios variam e mudam por programa.','Antes de parcelar, confirme se o débito correto foi selecionado e se o caixa sustenta as parcelas futuras.','CTN, art. 151, VI; leis e editais específicos da RFB, PGFN, estado ou município.','MEI, Simples Nacional','Achar que parcelar apaga multa ou garante certidão imediatamente; não pagar a primeira parcela.','Guarde o protocolo e acompanhe situação e vencimentos no portal do acordo.'],
    ['O que fazer ao cair na malha fina do IRPF?','Consulte o motivo no e-CAC, compare com documentos e retifique se houver erro antes de qualquer intimação, quando cabível.','A divergência pode envolver rendimentos, dependentes, despesas médicas, retenções ou informação de terceiros. Se houver intimação, responda pelo canal e prazo indicados com provas organizadas.','Informe de rendimento diferente do valor declarado pede correção ou comprovação, não apenas reenvio repetido.','Lei 9.250/1995; Decreto 9.580/2018; normas e procedimentos da RFB.','Pessoa Física','Ignorar caixa postal do e-CAC; anexar documentos sem índice ou sem relação com a divergência.','Baixe pendências, recibo e informes; organize comprovantes por item questionado.'],
    ['Como regularizar DAS do MEI atrasado?','Gere as guias vencidas no PGMEI com atualização calculada pelo sistema e confira também a declaração anual.','Atrasos podem gerar multa e juros; débitos podem ser parcelados nas condições disponíveis. Verifique pendências federais e eventuais débitos inscritos na PGFN.','Pagar as guias atuais não regulariza automaticamente competências antigas.','LC 123/2006; Resolução CGSN 140/2018; normas RFB/PGFN.','MEI','Emitir boleto em site não oficial; deixar de transmitir DASN-SIMEI por não ter faturamento.','Regularize mês a mês no portal oficial e salve os comprovantes.'],
    ['Como pedir certidão negativa ou positiva com efeitos de negativa?','A certidão depende da situação fiscal e das hipóteses legais de suspensão ou garantia do crédito.','Se houver débito, verifique pagamento, parcelamento, impugnação ou suspensão. A certidão positiva com efeitos de negativa tem tratamento legal próprio, não é favor do portal.','Um parcelamento ativo e adimplente pode ser relevante, mas confirme se todos os débitos que impedem emissão estão cobertos.','CTN, arts. 205 e 206; normas do ente emissor.','Lucro Presumido, Simples Nacional','Confundir certidão federal com municipal/estadual; assumir que pedido de parcelamento já suspendeu cobrança.','Consulte cada esfera e verifique validade e abrangência da certidão.']
  ]);
  add(CATEGORIES[9].name,[
    ['O que são IBS, CBS e Imposto Seletivo?','CBS é contribuição federal; IBS é imposto de estados e municípios; IS é seletivo sobre bens e serviços definidos em lei.','A reforma do consumo organiza tributos em modelo de IVA dual. IBS e CBS seguem regras harmonizadas, embora administrados por entes distintos; o IS tem finalidade e incidência próprias. O cronograma é gradual e tem exceções.','Uma empresa deve revisar cadastros e contratos antes de tratar o novo tributo como uma linha de imposto comum.','EC 132/2023; LC 214/2025; LC 227/2026.','Simples Nacional, Lucro Real, Lucro Presumido','Dizer que todos os tributos mudam no mesmo dia; afirmar que IPI desaparece sem ressalvas.','Acompanhe a versão vigente da lei e a regulamentação de cada obrigação.'],
    ['A não cumulatividade plena significa crédito para tudo?','Não. O modelo amplia a lógica de crédito, mas apropriação, restrições e uso seguem requisitos legais.','A lei prevê créditos vinculados às operações e condições de extinção do débito, além de vedações para uso pessoal e regras especiais. Documento fiscal, pagamento e enquadramento podem importar.','Uma despesa de uso pessoal do sócio não vira crédito da empresa apenas porque foi paga no cartão corporativo.','EC 132/2023; LC 214/2025, especialmente regras de crédito e uso pessoal.','Lucro Real','Tratar cada compra como crédito automático; não identificar adquirente ou documento fiscal.','Mapeie créditos por categoria de gasto e defina controles no ERP.'],
    ['O que é cobrança no destino?','Em linhas gerais, a receita do IBS é atribuída ao local de consumo/destino segundo critérios legais.','A identificação do destino depende do tipo de bem ou serviço e das regras de localização. Isso exige dados corretos de entrega, tomador e local de fruição.','Uma venda interestadual pode exigir revisar endereço de entrega e regras de documento fiscal, além do cadastro tributário.','EC 132/2023; LC 214/2025.','Comércio, Serviços, Indústria','Usar sempre endereço de cobrança como destino; desconsiderar operações com regras específicas.','Confira cadastro de cliente, local da operação e leiaute do documento fiscal.'],
    ['Como o split payment pode afetar o caixa?','O split payment pode separar e direcionar tributo na liquidação financeira conforme mecanismos legais e regulamentação.','Não significa que toda venda terá retenção automática idêntica desde o início. Implementação, participantes e procedimentos dependem da lei e de atos operacionais. A empresa deve avaliar conciliação e capital de giro.','Se parte do recebimento for segregada na liquidação, a previsão de caixa e conciliação com contas a receber precisam refletir isso.','LC 214/2025, regras de recolhimento e split payment; regulamentação vigente.','Comércio, Serviços, Lucro Real','Tratar valor bruto da venda como caixa disponível; mudar preço sem simular capital de giro.','Converse com adquirente, banco e ERP e teste a conciliação antes da implantação.'],
    ['Quem poderá receber cashback tributário?','A devolução é destinada a famílias elegíveis e seguirá critérios legais, cadastros e operacionalização oficial.','A LC define devolução personalizada de parte de tributos sobre consumo, com condições, percentuais e procedimentos. O benefício não é desconto universal na compra e depende de regulamentação e elegibilidade.','Uma família precisa cumprir requisitos de elegibilidade; o simples pedido de CPF na nota não garante cashback.','EC 132/2023; LC 214/2025; atos regulamentares.','Pessoa Física','Prometer valor fixo sem verificar renda, cadastro e regras; confundir com programa estadual de nota fiscal.','Consulte comunicação oficial e mantenha dados cadastrais atualizados.'],
    ['O Simples Nacional muda com IBS e CBS?','O Simples continua existindo; a empresa poderá manter IBS/CBS dentro do regime ou avaliar opção pelo regime regular desses tributos nos termos legais.','A opção pode afetar crédito para clientes, débitos, obrigações e caixa. Em 2026 houve calendário especial para opções com efeito em períodos de 2027; consulte situação e prazo oficial vigente antes de agir.','Uma empresa B2B pode avaliar se o cliente valoriza crédito; um negócio B2C pode ter outra dinâmica. A decisão depende da cadeia e dos custos.','LC 123/2006; LC 214/2025 e LC 227/2026; Resoluções CGSN vigentes.','Simples Nacional','Supor que a opção regular muda IRPJ/CSLL do Simples; decidir só pelo crédito do cliente.','Simule cenários com dados reais de compras e vendas e confirme prazo no Portal do Simples.']
  ]);
  /* FAQ ampliado: os aliases fazem siglas e termos informais entrarem na busca. */
  function qa(category,question,resposta,detalhada,exemplo,baseLegal,tags,sinonimos=[]){Q.push({category,question,resposta,detalhada,exemplo,baseLegal,tags:tags.split(',').map(x=>x.trim()),sinonimos,erros:'Confundir eventos, papéis ou regras de outra competência/UF; não reconciliar documento, escrituração e guia.',tip:'Feche a trilha documental, guarde recibos e confirme a orientação no portal oficial antes de transmitir ou recolher.',relacionadas:[],id:'q'+(Q.length+1)})}
  const rf='IN RFB 2.043/2021; Manual e FAQ oficial da EFD-Reinf vigentes.', df='EC 87/2015; LC 87/1996; LC 190/2022; legislação da UF de destino.';
  [
    ['Quem é obrigado a entregar a EFD-Reinf?','Envia quem estiver sujeito aos eventos da norma, como retenções previdenciárias, retenções federais em pagamentos e fatos rurais/CPRB.','Não depende apenas do porte ou regime. A IN 2.043/2021 define sujeitos passivos e eventos. A obrigação ocorre quando há fatos a escriturar; a Receita dispensa “sem movimento” na ausência de fatos.','Empresa que contrata serviço com retenção pode informar R-2010; contribuinte sem fatos abrangidos pode não enviar naquele mês.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['reinf','efd reinf']],
    ['Qual é o prazo mensal da EFD-Reinf?','Em regra, dia 15 do mês seguinte; sem expediente bancário, antecipe para o dia útil anterior.','R-3010 tem regra própria: até dois dias úteis após o espetáculo. Confirme calendário e norma atual antes de fechar.','Fatos de março seguem, em regra, até 15 de abril, respeitado o calendário bancário.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['reinf','prazo reinf']],
    ['O que é o R-1000?','É o cadastro do declarante e das informações que identificam a empresa ou pessoa na Reinf.','Evento de tabela necessário para iniciar os eventos periódicos. Mudanças precisam respeitar vigência e leiaute; alterações devem refletir o cadastro completo solicitado.','Antes do primeiro R-2010, confira se o R-1000 foi aceito e cobre a competência.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['r-1000','cadastro reinf']],
    ['Qual a diferença entre R-2010 e R-2020?','R-2010 informa retenção previdenciária em serviço tomado; R-2020 informa retenção em serviço prestado.','Tomador e prestador informam seus papéis próprios, com base na nota, no contrato e nas regras de retenção.','Na mesma prestação, o tomador pode declarar R-2010 e o prestador R-2020.', 'Lei 8.212/1991, art. 31; IN RFB 2.110/2022; leiaute Reinf.','Lucro Real, Lucro Presumido, Simples Nacional',['r-2010','r-2020','retenção de inss']],
    ['Onde informo IRRF, PIS, Cofins e CSLL retidos?','Na série R-4000, conforme beneficiário e natureza do pagamento; rendimentos do trabalho são informados no eSocial.','R-4010: pessoa física sem relação de trabalho; R-4020: pessoa jurídica; R-4040: beneficiário não identificado; R-4080: retenção no recebimento, quando aplicável.','Pagamento a fornecedor PJ com retenções exige classificar natureza do rendimento e beneficiário.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['r-4010','r-4020','irrf reinf','pis cofins csll']],
    ['A EFD-Reinf substitui o eSocial?','Não. São complementares: eSocial trata informações do trabalho; Reinf recebe outros fatos e retenções.','As duas escriturações alimentam a DCTFWeb. Classifique o vínculo e evite informar o mesmo fato nos dois ambientes.','Folha e pró-labore no ambiente de trabalho; retenção em serviço contratado pode ir à Reinf.', 'Decreto 8.373/2014; IN RFB 2.043/2021; manuais dos sistemas.','Lucro Real, Lucro Presumido, Simples Nacional',['esocial','reinf']],
    ['Como os eventos geram a guia na DCTFWeb?','Transmita e feche os eventos, confira totalizadores na DCTFWeb, transmita a declaração e emita DARF numerado.','R-2099 fecha a série R-2000; R-4099 fecha a R-4000. Os dados consolidados alimentam a DCTFWeb para conferência e confissão.','Evento aceito sem fechamento pode não refletir o total esperado na declaração.', 'IN RFB 2.005/2021 e alterações; Manual DCTFWeb; FAQ Reinf.','Lucro Real, Lucro Presumido, Simples Nacional',['dctfweb','darf reinf']],
    ['Como usar PER/DCOMP com crédito de retenção?','Créditos de retenção podem ser usados no PER/DCOMP Web nos casos autorizados; a escrituração de origem precisa estar correta.','Se R-2020 estiver errado, corrija a Reinf, feche novamente, atualize a DCTFWeb e recarregue dados no PER/DCOMP. Compensação depende de saldo e regras legais.','Retenção de R$ 900 incorreta não deve ser compensada até corrigir a origem e reconciliar a declaração.','IN RFB 2.055/2021; Perguntas e Respostas DCTFWeb; IN RFB 2.043/2021.','Lucro Real, Lucro Presumido',['perdcomp','crédito retenção']],
    ['Como retificar evento da EFD-Reinf?','Reabra a série, retifique ou exclua o evento, confira totalizadores e feche novamente.','R-2098 trata a reabertura da série R-2000; R-4099 atua na série R-4000; R-9000 exclui evento indevido. Confira DCTFWeb e guia depois.','Evento duplicado pode exigir exclusão, novo fechamento e revisão do débito consolidado.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['retificar reinf','r-9000']],
    ['Quais multas podem ocorrer por atraso na Reinf?','Atraso, omissão ou inexatidão pode gerar penalidade acessória; o cálculo depende da regra vigente e da situação.','Não confunda sanção da escrituração com MAED da DCTFWeb, que é declaração diferente. Verifique a norma sancionatória aplicável antes de estimar valores.','Omissão de retenção pode gerar diferença de tributo e penalidade; ausência de fatos não exige evento sem movimento.','IN RFB 2.043/2021; MP 2.158-35/2001, art. 57, e normas posteriores.','Lucro Real, Lucro Presumido, Simples Nacional',['multa reinf','atraso reinf']],
    ['Preciso enviar EFD-Reinf sem movimento?','Não. A orientação oficial dispensa o envio “sem movimento” se não houver fato sujeito à escrituração.','Isso não dispensa outras obrigações, como eSocial, DCTFWeb ou declarações específicas eventualmente devidas.','Sem retenção ou outro evento Reinf no mês, pode não haver envio Reinf, mas a folha continua no eSocial se houver empregados.',rf,'Lucro Real, Lucro Presumido, Simples Nacional',['sem movimento reinf']]
  ].forEach(x=>qa('EFD-Reinf',...x));
  [
    ['O que é o DIFAL?','É a diferença entre alíquota interna do destino e interestadual, nas hipóteses constitucionais e legais.','EC 87/2015 e LC 190/2022 regulam vendas interestaduais a consumidor final não contribuinte; LC 87/1996 também trata entradas para uso/consumo ou ativo.','Base hipotética R$ 1.000; interna 18%, interestadual 12%: diferença simples de R$ 60, antes de FCP e regras locais.',df,'Comércio, Simples Nacional, Lucro Presumido, Lucro Real',['difal','diferencial de aliquota','icms difal']],
    ['Quem recolhe DIFAL quando o destinatário é contribuinte?','Em aquisição para uso/consumo ou ativo, normalmente o destinatário apura; a UF pode atribuir responsabilidade ao remetente em situações específicas.','Finalidade da aquisição, inscrição, ST e legislação estadual mudam a obrigação. Compra para revenda tem tratamento diferente.','Compra de máquina de outra UF para imobilizado exige avaliar DIFAL e crédito/CIAP separadamente.',df,'Comércio, Lucro Real, Lucro Presumido',['difal contribuinte']],
    ['Quem recolhe na venda a consumidor final não contribuinte?','Em operações alcançadas, remetente ou prestador recolhe ao destino conforme LC 87/1996, LC 190/2022 e regra local.','Identifique consumidor, endereço de entrega, regime do vendedor e eventuais inscrições; há orientações próprias para Simples e por UF.','Venda online a pessoa física de outra UF pede regra fiscal do destino, FCP e guia correspondente.',df,'Comércio, Simples Nacional',['difal não contribuinte','e-commerce']],
    ['DIFAL incide em uso/consumo e ativo imobilizado?','Pode incidir na entrada interestadual de bens destinados a uso/consumo ou ativo de contribuinte, conforme regra estadual.','DIFAL e crédito do ICMS são análises separadas. Crédito em ativo pode exigir controle CIAP e observar limites legais.','Computador para uso administrativo pode gerar análise de DIFAL sem gerar crédito integral automático.','LC 87/1996, arts. 20, 23 e 33; norma estadual.','Lucro Real, Lucro Presumido, Simples Nacional',['uso consumo','ativo imobilizado']],
    ['Como funciona o DIFAL no e-commerce?','Venda interestadual a consumidor final exige identificar destino e revisar responsabilidade do vendedor pelo DIFAL e FCP.','UF de entrega, perfil do comprador, benefício, inscrição e regime influenciam a apuração.','Pedido de R$ 1.000 entregue em outra UF usa a regra do destino, não apenas o endereço da loja.',df,'Comércio, Simples Nacional',['difal e-commerce','venda interestadual']],
    ['O que é FCP no cálculo do DIFAL?','É adicional estadual de combate à pobreza, aplicável a produtos e situações previstos pela UF.','Alíquota, produtos, base e guia variam. Pode somar-se ao DIFAL, mas não é universal.','Base hipotética R$ 1.000 com FCP hipotético 2% daria adicional simples de R$ 20 se a operação estiver alcançada.','CF/1988, ADCT art. 82; EC 87/2015; legislação estadual.','Comércio, Lucro Real, Lucro Presumido',['fcp','fundo de combate a pobreza']],
    ['Existe partilha entre origem e destino?','A partilha transitória da EC 87/2015 terminou; confira regra atual da LC 190/2022 e estado envolvido.','Não reutilize percentuais de anos de transição em parametrizações atuais; a atribuição do diferencial segue regra vigente e detalhes locais.','Planilha antiga com percentuais de partilha pode gerar recolhimento incorreto.',df,'Comércio, Lucro Real, Lucro Presumido',['partilha difal']],
    ['DIFAL, antecipação e ICMS-ST são a mesma coisa?','Não. DIFAL compara alíquotas para consumidor final; antecipação adianta ICMS próprio; ST atribui recolhimento de etapas a responsável.','Podem coexistir regras na cadeia, conforme produto, finalidade e UF. Leia a base legal e o código de receita da guia.','Compra para revenda pode ter ST; bem de uso pode ter DIFAL; outra entrada pode cair em antecipação.','CF/1988, art. 155; LC 87/1996, arts. 6º a 10; normas estaduais.','Comércio, Simples Nacional',['st','substituicao tributaria','antecipação']],
    ['Como escriturar e recolher o DIFAL?','Use documento e registros EFD adequados; recolha por GNRE, DARE ou apuração estadual conforme a UF.','CFOP, CST/CSOSN, código, prazo e guia variam por operação, perfil e estado. Goiás mantém orientação e portal próprios.','Contribuinte inscrito pode apurar em conta fiscal; não inscrito pode recolher por operação, conforme regra local.','Ajustes SINIEF; Guia Prático EFD ICMS/IPI; legislação estadual.','Comércio, Lucro Real, Lucro Presumido',['gnre difal','dare difal','nota de entrada']],
    ['Como tratar DIFAL no Simples Nacional?','Não presuma incidência nem dispensa: considere operação, legislação atual e entendimento oficial da UF.','Venda B2C e aquisição para uso/ativo podem ter tratamentos distintos. Consulte LC 123/2006, LC 190/2022 e orientação estadual atual.','Venda de optante do Simples para consumidor de GO deve ser validada no portal da Secretaria da Economia de Goiás.',df,'Simples Nacional',['difal simples nacional']]
  ].forEach(x=>qa('DIFAL',...x));
