  async function readNfseFiles(){const company=document.getElementById('nfseCnpj').value;let files=[...(nfseFilesInput.files||[])],zips=[...(nfseZipInput.files||[])],texts=[],errors=[];if(!files.length&&!zips.length){nfseStatus.textContent='Selecione pelo menos um XML ou ZIP.';return}for(const f of files){try{texts.push({name:f.name,text:await f.text()})}catch(e){errors.push(`${f.name}: falha ao ler arquivo`)}}for(const z of zips){try{for await(const x of unzipXml(z)){if(x.error)errors.push(`${x.name}: ${x.error}`);else if(x.text)texts.push(x)}}catch(e){errors.push(`${z.name}: ${e.message||'falha ao abrir ZIP'}`)}}let records=[];for(const x of texts){try{records.push(...parseNfseXml(x.text,x.name,company))}catch(e){errors.push(`${x.name}: ${e.message||'não foi possível interpretar'}`)}}const unique=new Map();let duplicated=0;for(const n of records){if(unique.has(n.key)){duplicated++;continue}unique.set(n.key,n)}nfseData=[...unique.values()];renderNfse();nfseStatus.textContent=`Leitura concluída: ${nfseData.length} nota(s) reconhecida(s), ${duplicated} duplicata(s) removida(s), ${errors.length} arquivo(s) com aviso/erro. ${errors.slice(0,8).join(' · ')}${errors.length>8?' · …':''} A ausência de um campo pode refletir o leiaute do município.`}
