  function parsePgdasActivityRates(lines,file){const out=[];for(let i=0;i<lines.length;i++){if(!normalizeText(lines[i].text).includes('valor do debito por tributo para a atividade'))continue;let revenueIndex=-1,revenue=null;for(let j=i+1;j<Math.min(lines.length,i+16);j++){if(normalizeText(lines[j].text).includes('receita bruta informada')){const vals=pgdasMoneyValues(lines[j].text);if(vals.length){revenue=vals.at(-1).value;revenueIndex=j}break}}if(!(revenue>0)||revenueIndex<0)continue;const activity=lines.slice(i+1,revenueIndex).map(x=>x.text.trim()).filter(Boolean).join(' ').replace(/\s+/g,' ').slice(0,300);let debit=null,taxes=null;for(let j=revenueIndex+1;j<Math.min(lines.length,revenueIndex+10);j++){const line=lines[j].text.trim(),norm=normalizeText(line);if(!line||norm.startsWith('parcela'))continue;const vals=pgdasMoneyValues(line);if(vals.length>=9){taxes=pgdasTaxAmounts(vals);debit=taxes?.Total??vals.at(-1).value;break}if(vals.length>=8&&debit===null)debit=vals.at(-1).value}if(Number.isFinite(debit)&&debit>=0)out.push({activity:activity||'Atividade sem descrição',revenue,debit,rate:debit/revenue*100,taxes,file})}return out}
