    // O relatório oficial de Receitas Brutas anteriores apresenta vários pares mês/valor na mesma linha.
    let historyMarket=null;for(const item of lines){const norm=normalizeText(item.text);if(/2\s+2\s+1/.test(norm)&&norm.includes('mercado interno')){historyMarket='interno';continue}if(/2\s+2\s+2/.test(norm)&&norm.includes('mercado externo')){historyMarket='externo';continue}if(/2\s+3/.test(norm)&&norm.includes('folha'))historyMarket=null;if(!historyMarket)continue;const pairRe=/\b(0?[1-9]|1[0-2])\s*[/.\-]\s*(20\d{2})\s+((?:\d{1,3}(?:\.\d{3})*|\d+),\d{2})\b/g;for(const match of item.text.matchAll(pairRe)){const revenue=parseBookAmount(match[3]);if(Number.isFinite(revenue)&&revenue>=0)rows.push({period:match[2]+'-'+String(match[1]).padStart(2,'0'),revenue,market:historyMarket,source:file.name,page:item.page})}}
