  pgdasPdfInput.addEventListener('change',async()=>{const files=[...pgdasPdfInput.files||[]];if(!files.length)return;pgdasImportStatus.textContent='Lendo PDF(s) no navegador…';pgdasImportPreview.innerHTML='';applyPgdasImport.hidden=true;usePgdasRbt.hidden=true;const results=[],errors=[];for(const file of files){try{if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))throw new Error(file.name+': selecione apenas arquivos PDF.');results.push(await readPgdasPdf(file))}catch(err){errors.push(err.message||file.name+': erro de leitura')}}const merged=new Map(),duplicates=[];for(const result of results){for(const row of result.rows){if(merged.has(row.period)&&Math.abs(merged.get(row.period).revenue-row.revenue)>.01)duplicates.push(row.period);merged.set(row.period,row)}}const rbtCandidates=results.filter(x=>x.rbt12>0),paCandidates=results.filter(x=>x.paRevenue>0&&x.paDas>=0),paResult=paCandidates.at(-1),parsed={rows:[...merged.values()],rbt12:rbtCandidates.at(-1)?.rbt12??null,pa:results.map(x=>x.pa).filter(Boolean).at(-1)||null,paRevenue:paResult?.paRevenue??null,paDas:paResult?.paDas??null,activityRates:results.flatMap(x=>x.activityRates||[]),declaredTaxes:results.map(x=>x.declaredTaxes).filter(Boolean).at(-1)||null,files:results.map(x=>x.file)};showPgdasImport(parsed,errors);if(duplicates.length)pgdasImportStatus.insertAdjacentHTML('beforeend','<br><b>Atenção:</b> competências repetidas com valores diferentes: '+[...new Set(duplicates)].join(', ')+'. Confira qual arquivo é o correto.');pgdasPdfInput.value=''});
  applyPgdasImport.addEventListener('click',()=>{const rows=[...pgdasImportPreview.querySelectorAll('.pgdas-import-value')].map(input=>({...pgdasParsed.rows[Number(input.dataset.index)],revenue:Math.max(0,Number(input.value)||0)}));if(!rows.length)return;const target=pgdasParsed.pa||(()=>{const last=rows.map(x=>x.period).sort().at(-1);const [y,m]=last.split('-').map(Number),d=new Date(y,m,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')})();const validPeriods=new Set(Array.from({length:12},(_,i)=>{const [y,m]=target.split('-').map(Number),d=new Date(y,m-1-(12-i),1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}));const selected=rows.filter(x=>validPeriods.has(x.period));if(!selected.length){pgdasImportStatus.insertAdjacentHTML('beforeend','<br><b>Nenhuma competência encontrada dentro dos 12 meses anteriores ao período de apuração.</b> Revise a competência detectada ou preencha manualmente.');return}const overlaps=selected.filter(x=>(+historyData[x.period]?.revenue||0)>0);if(overlaps.length&&!confirm('Já existem valores em '+overlaps.map(x=>x.period.slice(5,7)+'/'+x.period.slice(0,4)).join(', ')+'. Deseja substituí-los pelos valores deste PDF?'))return;for(const row of selected)historyData[row.period]={...(historyData[row.period]||{}),revenue:row.revenue};historyTarget.value=target;localStorage.setItem('cc_history12',JSON.stringify(historyData));renderHistory();const missing=[...validPeriods].filter(p=>!selected.some(x=>x.period===p));pgdasImportStatus.insertAdjacentHTML('beforeend','<br><b>'+selected.length+' competência(s) aplicada(s) ao Histórico 12m neste navegador.</b> '+(missing.length?'Ainda faltam '+missing.length+' mês(es); revise a tabela.':'Os 12 meses anteriores ao PA foram encontrados.')+' A folha foi preservada como estava.');});
  usePgdasRbt.addEventListener('click',()=>{const input=document.getElementById('simRbt');if(!input||!pgdasParsed.rbt12)return;input.value=Number(pgdasParsed.rbt12).toFixed(2);calcSimples();showPage('calculadoras');document.querySelector('[data-open-profile="simples"]')?.click()});
  historyTarget.addEventListener('change',renderHistory);renderHistory();document.getElementById('useHistory').addEventListener('click',()=>{const ps=historyPeriods(),rev=ps.reduce((a,k)=>a+(+historyData[k]?.revenue||0),0),pay=ps.reduce((a,k)=>a+(+historyData[k]?.payroll||0),0);simRbt.value=rev.toFixed(2);simFs12.value=pay.toFixed(2);calcSimples();showPage('calculadoras');document.querySelector('[data-open-profile="simples"]')?.click()});document.getElementById('exportHistory').addEventListener('click',()=>{const payload={app:'Portal Contábil',updatedAt:new Date().toISOString(),period:historyTarget.value,months:historyData};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='historico-fiscal-conta-clara.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});document.getElementById('importHistory').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const o=JSON.parse(await f.text()),data=o.months||o;if(!data||typeof data!=='object'||Array.isArray(data))throw new Error();historyData=data;localStorage.setItem('cc_history12',JSON.stringify(historyData));if(o.period)historyTarget.value=o.period;renderHistory();historySummary.insertAdjacentHTML('beforeend','<br><b>Dados importados.</b>')}catch(err){historySummary.innerHTML='<b>Não foi possível importar.</b> Escolha um JSON exportado pelo portal.'}e.target.value=''});
  // Calculadora genérica de tributos: fórmula e base escolhidas pelo usuário.
  const taxType=document.getElementById('taxCalcType'),taxDifMethod=document.getElementById('taxDifMethod'),taxBase=document.getElementById('taxCalcBase'),taxRate=document.getElementById('taxCalcRate'),taxExtra=document.getElementById('taxCalcExtra'),taxFcp=document.getElementById('taxCalcFcp'),taxCredit=document.getElementById('taxCalcCredit'),taxThreshold=document.getElementById('taxCalcThreshold'),taxCalcResult=document.getElementById('taxCalcResult');
  function updateTaxCalcLabels(){const t=taxType.value,label=document.querySelector('label[for="taxCalcRate"]'),extra=document.querySelector('label[for="taxCalcExtra"]'),fcpWrap=document.getElementById('taxCalcFcp').parentElement,thresholdWrap=taxThreshold.parentElement,difMethodWrap=document.getElementById('taxDifMethodWrap');difMethodWrap.hidden=t!=='difal';label.textContent=t==='difal'?'Alíquota interestadual (%)':t==='irpj'?'Alíquota básica do IRPJ (%)':'Alíquota (%) — confirme vigente';extra.textContent=t==='difal'?'Alíquota interna do destino (%)':t==='irpj'?'Adicional do IRPJ (%)':'Alíquota interna / parâmetro adicional (%)';fcpWrap.hidden=t!=='difal';thresholdWrap.hidden=t!=='irpj'}
  function runTaxCalc(){const base=Math.max(0,+taxBase.value||0),rate=+taxRate.value||0,extra=+taxExtra.value||0,credit=Math.max(0,+taxCredit.value||0),threshold=Math.max(0,+taxThreshold.value||0),fcp=Math.max(0,+taxFcp.value||0),t=taxType.value;if(!base||!taxRate.value){taxCalcResult.innerHTML='Informe uma base maior que zero e a alíquota aplicável. Consulte a legislação vigente.';return}let gross=0,formula='';if(t==='difal'){if(taxDifMethod.value==='gross'&&extra>=100){taxCalcResult.textContent='Para o método de gross-up, a alíquota interna deve ser inferior a 100%.';return}const delta=Math.max(0,extra-rate),d=taxDifMethod.value==='gross'?(base/(1-extra/100))*delta/100:base*delta/100;gross=d+base*fcp/100;formula=`DIFAL ${taxDifMethod.value==='gross'?'por dentro (gross-up)':'por fora'}: ${taxDifMethod.value==='gross'?`${money(base)} ÷ (1 − ${extra}%) × (${extra}% − ${rate}%)`:`${money(base)} × (${extra}% − ${rate}%)`} + FCP ${money(base)} × ${fcp}%`}else if(t==='irpj'){gross=base*rate/100+Math.max(0,base-threshold)*extra/100;formula=`Base ${money(base)} × ${rate}% + adicional sobre excedente de ${money(threshold)} × ${extra}%`}else{gross=base*rate/100;formula=`Base ${money(base)} × ${rate}% (${t==='icms'?'ICMS simples, sem substituição/benefícios':t.toUpperCase()})`}const due=Math.max(0,gross-credit);taxCalcResult.innerHTML=`<b>Estimativa${t==='difal'?` — DIFAL ${taxDifMethod.value==='gross'?'gross-up (base recalculada)':'direto por fora'} + FCP`:''}: ${money(due)}</b><br>Valor antes dos créditos informados: ${money(gross)} · Crédito/abatimento informado: ${money(credit)}<br>Memória: ${esc(formula)}<br><span class="fine">Fórmula didática; não valida incidência, contribuinte, base, adicional, redução, retenção, crédito ou guia.</span>`}
  taxType.addEventListener('change',()=>{updateTaxCalcLabels();runTaxCalc()});taxDifMethod.addEventListener('change',runTaxCalc);document.getElementById('runTaxCalc').addEventListener('click',runTaxCalc);[taxBase,taxRate,taxExtra,taxFcp,taxCredit,taxThreshold].forEach(x=>x.addEventListener('input',runTaxCalc));updateTaxCalcLabels();
