  const CALC_GROUPS={'Regimes e Simples':'Regime unificado','Federais':'Federal','Estaduais':'Estadual','Municipais':'Municipal','Folha e contribuições':'Trabalhista,Previdenciário','Planejamento':'Planejamento'};
  function calculatorGroup(x){let group;if(x.profile==='simples'||x.profile==='mei'||x.profile==='presumido'||x.profile==='real')group='Regimes e Simples';else if(x.profile==='comparador')group='Planejamento';else if(x.profile==='folha'||x.profile==='prolabore'||x.tax==='inss')group='Folha e contribuições';else if(x.sphere==='Federal')group='Federais';else if(x.sphere==='Estadual')group='Estaduais';else if(x.sphere==='Municipal')group='Municipais';else group='Planejamento';return calcProfileFilter.value?`${calcProfileFilter.value} · ${group}`:group}
  const calcCatalog=document.getElementById('calculatorCatalog'),calcProfileFilter=document.getElementById('calcProfileFilter'),calcSearch=document.getElementById('calcSearch');
  function renderCalculatorCatalog(){const profile=calcProfileFilter.value,term=normalizeText(calcSearch.value);let items=CALC_CATALOG.filter(x=>(!profile||x.profiles.includes(profile))&&(!term||normalizeText([x.title,x.sphere,x.kind,x.desc,...x.profiles].join(' ')).includes(term)));const groups={};items.forEach(x=>(groups[calculatorGroup(x)]??=[]).push(x));calcCatalog.innerHTML=Object.entries(groups).map(([group,list])=>`<details class="calc-tree-group" open><summary>${esc(group)} <span class="fine">(${list.length})</span></summary>${list.map(x=>`<button type="button" class="calc-tree-item" ${x.profile?`data-open-profile="${x.profile}"`:`data-open-tax="${x.tax}"`} aria-current="false">${esc(x.title)}</button>`).join('')}</details>`).join('')||'<div class="empty">Nenhuma calculadora encontrada. Ajuste a busca ou o perfil.</div>'}
  function openCalculator(button){let panelId;if(button.dataset.openProfile)panelId='calc-'+button.dataset.openProfile;else if(button.dataset.openTax==='difal')panelId='calc-difal';else{panelId='calc-tributo';taxType.value=button.dataset.openTax;updateTaxCalcLabels();runTaxCalc()}const panel=document.getElementById(panelId);if(!panel)return;document.querySelectorAll('#calcStage .calc-panel').forEach(x=>x.hidden=x!==panel);calcEmpty.hidden=true;calcCatalog.querySelectorAll('.calc-tree-item').forEach(x=>x.setAttribute('aria-current',String(x===button)));panel.scrollIntoView({block:'start'});calcStage.scrollTop=0}
  calcProfileFilter.addEventListener('change',renderCalculatorCatalog);calcSearch.addEventListener('input',renderCalculatorCatalog);renderCalculatorCatalog();calcCatalog.addEventListener('click',e=>{const b=e.target.closest('[data-open-profile],[data-open-tax]');if(b)openCalculator(b)});const firstCalc=calcCatalog.querySelector('[data-open-profile="simples"]');if(firstCalc)openCalculator(firstCalc);

  const compResult=document.getElementById('compResult');function calcComp(){const set=document.getElementById('compSetor').value,rec=+document.getElementById('compFaturamento').value||0,marg=+document.getElementById('compMargem').value||0,meiEligible=document.getElementById('compMeiEligible').checked;let notes=['MEI/SIMEI: inclua somente se a empresa atender aos requisitos vigentes; confira ocupação, receita e demais condições no Portal do Empreendedor.','Simples Nacional: confira limite, sublimite estadual, atividade, anexo e vedações antes de considerar a opção.'];notes.push(set==='Serviços'?'Para serviços, examine fator R, ISS, folha e perfil dos tomadores.':set==='Comércio'?'Para comércio, examine ICMS, ST, monofásicos, estoque e créditos.':set==='Indústria'?'Para indústria, examine IPI, ICMS, créditos, estoque e cadeia de insumos.':'Separe receita e custo por atividade.');notes.push(marg<8?'Margem informada é baixa: fluxo de caixa, créditos e custo efetivo merecem simulação detalhada.':'Compare margem real com bases presumidas e folha.');const ids=[['MEI (se elegível)','compMei'],['Simples Nacional','compSimples'],['Lucro Presumido','compPresumido'],['Lucro Real','compReal']];const estimates=ids.map(([name,id])=>{const input=document.getElementById(id),isMei=name.startsWith('MEI'),enabled=!isMei||meiEligible;return {name,rate:!enabled||input.value===''?null:+input.value,value:!enabled||input.value===''?null:rec*(+input.value)/100,notEligible:isMei&&!meiEligible&&input.value!==''}});const valid=estimates.filter(x=>x.value!==null);const lower=valid.length?Math.min(...valid.map(x=>x.value)):null;const comparison=estimates.map(x=>`<li>${x.notEligible?'MEI: confirme elegibilidade para incluir na comparação':`${x.name}: ${x.value===null?'informe a carga efetiva':`${money(x.value)} (${x.rate.toLocaleString('pt-BR',{maximumFractionDigits:3})}%)`}${x.value!==null&&x.value===lower?' · menor estimativa informada':''}`}</li>`).join('');compResult.innerHTML=`<b>Estimativa anual sobre ${money(rec)}:</b><ul>${comparison}</ul><b>Leitura inicial:</b><ul>${notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><span class="fine">A menor estimativa não significa, sozinha, que o regime seja permitido ou adequado.</span>`}['compSetor','compFaturamento','compMargem','compMei','compMeiEligible','compSimples','compPresumido','compReal'].forEach(id=>document.getElementById(id).addEventListener('input',calcComp));document.getElementById('compMeiEligible').addEventListener('change',calcComp);calcComp();
  // Converte totais do mesmo período em percentuais e pode preencher os campos do comparador.
  const guideRateButton=document.getElementById('guideRateButton'),guideFillCompare=document.getElementById('guideFillCompare'),guideRateResult=document.getElementById('guideRateResult');let guideRates=null;
  function calcGuideRates(){const revenue=Number(document.getElementById('guideRevenue').value),profitInput=document.getElementById('guideProfit').value,profit=profitInput===''?null:Number(profitInput),meiEligible=document.getElementById('guideMeiEligible').checked;if(!(revenue>0)){guideRates=null;guideFillCompare.disabled=true;guideRateResult.textContent='Informe uma receita bruta maior que zero para calcular os percentuais.';return}const rows=[['MEI','guideMeiTaxes'],['Simples Nacional','guideSimpleTaxes'],['Lucro Presumido','guidePresumedTaxes'],['Lucro Real','guideRealTaxes']];guideRates={revenue,margin:profit===null?null:(profit/revenue)*100};const lines=[];if(guideRates.margin!==null)lines.push(`<li>Margem aproximada: ${guideRates.margin.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}% (${money(profit)} ÷ ${money(revenue)} × 100)</li>`);rows.forEach(([name,id])=>{const raw=document.getElementById(id).value;if(raw===''){guideRates[name]=null;lines.push(`<li>${name}: informe o total do período para obter a carga efetiva.</li>`);return}const taxes=Number(raw);if(taxes<0){guideRates=null;guideFillCompare.disabled=true;guideRateResult.textContent='Os totais de tributos não podem ser negativos.';return}if(name==='MEI'&&!meiEligible){guideRates[name]=null;lines.push('<li>MEI: confirme a elegibilidade atual no SIMEI para incluir este cenário.</li>');return}const rate=taxes/revenue*100;guideRates[name]=rate;lines.push(`<li>${name}: ${rate.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:4})}% (${money(taxes)} ÷ ${money(revenue)} × 100)</li>`)});guideRateResult.innerHTML=`<b>Percentuais para o período informado</b><ul>${lines.join('')}</ul><span class="fine">Para o MEI, confirme a elegibilidade; no Presumido e Real, use os totais de uma apuração validada. A conta não apura os tributos.</span>`;guideFillCompare.disabled=!rows.some(([name])=>guideRates[name]!==null);}
  guideRateButton.addEventListener('click',calcGuideRates);
  guideFillCompare.addEventListener('click',()=>{if(!guideRates)return;document.getElementById('compFaturamento').value=guideRates.revenue;if(guideRates.margin!==null)document.getElementById('compMargem').value=guideRates.margin;const guideMeiEligible=document.getElementById('guideMeiEligible').checked;document.getElementById('compMeiEligible').checked=guideMeiEligible;[['MEI','compMei'],['Simples Nacional','compSimples'],['Lucro Presumido','compPresumido'],['Lucro Real','compReal']].forEach(([name,id])=>{const input=document.getElementById(id);input.value=guideRates[name]!==null&&guideRates[name]!==undefined?guideRates[name]:''});['compFaturamento','compMargem','compMei','compSimples','compPresumido','compReal'].forEach(id=>document.getElementById(id).dispatchEvent(new Event('input',{bubbles:true})));document.getElementById('compMeiEligible').dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('.calc-route[data-calc-profile="comparador"]')?.click()});

  /* Glossário pesquisável */
  const G=[['Adicional de IRPJ','Parcela adicional calculada sobre a base que ultrapassa limite legal no período.'],['Alíquota efetiva','Percentual resultante aplicado à receita após fórmula própria do regime, como no Simples.'],['Ativo','Bens e direitos controlados pela entidade.'],['Balanço patrimonial','Demonstração da posição financeira e patrimonial em uma data.'],['CBS','Contribuição sobre Bens e Serviços, tributo federal criado pela reforma do consumo.'],['CFOP','Código Fiscal de Operações e Prestações que identifica a natureza da operação.'],['CNAE','Classificação Nacional de Atividades Econômicas usada para identificar atividades.'],['Conciliação','Conferência entre registros contábeis e documentos ou extratos de origem.'],['CSLL','Contribuição Social sobre o Lucro Líquido.'],['DAS','Documento de Arrecadação do Simples Nacional.'],['DCTFWeb','Declaração federal que consolida débitos para confissão e emissão de documento de arrecadação, conforme regras vigentes.'],['Débito tributário','Obrigação de pagar tributo e acréscimos legalmente incidentes.'],['Depreciação','Alocação sistemática do valor depreciável de ativo ao longo da vida útil.'],['DRE','Demonstração do Resultado do Exercício ou período.'],['ECD','Escrituração Contábil Digital.'],['ECF','Escrituração Contábil Fiscal.'],['eSocial','Sistema de escrituração de informações trabalhistas, previdenciárias e fiscais.'],['Fator R','Relação entre folha e receita usada para determinadas atividades do Simples Nacional.'],['FGTS','Fundo de Garantia do Tempo de Serviço.'],['IBS','Imposto sobre Bens e Serviços, de competência compartilhada entre estados, DF e municípios.'],['ICMS','Imposto estadual sobre circulação de mercadorias e serviços definidos na Constituição.'],['IPI','Imposto sobre Produtos Industrializados.'],['ISS','Imposto municipal sobre serviços previstos em lei complementar.'],['IRPJ','Imposto de Renda da Pessoa Jurídica.'],['IRPF','Imposto de Renda da Pessoa Física.'],['Lucro contábil','Resultado apurado pela contabilidade segundo normas aplicáveis.'],['Lucro real','Regime de apuração do IRPJ/CSLL a partir do lucro líquido ajustado fiscalmente.'],['Lucro presumido','Regime que utiliza percentuais legais para presumir base de IRPJ/CSLL.'],['NCM','Nomenclatura Comum do Mercosul para classificação de mercadorias.'],['Não cumulatividade','Mecanismo que permite, sob requisitos legais, descontar créditos de tributo em etapas anteriores.'],['Passivo','Obrigações presentes da entidade.'],['PIS/Cofins','Contribuições federais sobre receitas, com regimes e regras distintos.'],['Pró-labore','Remuneração do sócio ou administrador pelo trabalho prestado à empresa.'],['RBT12','Receita bruta acumulada nos 12 meses anteriores, usada no cálculo do Simples.'],['Regime de caixa','Reconhecimento baseado em recebimentos e pagamentos, quando permitido.'],['Regime de competência','Reconhecimento de receitas e despesas quando ocorrem economicamente.'],['Split payment','Mecanismo de segregação e recolhimento de tributo no fluxo de pagamento, conforme lei e regulamentação.'],['SPED','Sistema Público de Escrituração Digital.'],['Substituição tributária','Atribuição legal a contribuinte de recolher tributo devido em etapas subsequentes.'],['Tributo','Prestação pecuniária compulsória instituída em lei, nos termos do CTN.'],['Alíquota nominal','Percentual publicado para uma faixa ou hipótese legal antes dos ajustes que formam a alíquota efetiva. No Simples, não é necessariamente o percentual total aplicado à receita mensal.'],['Antecipação de ICMS','Recolhimento do ICMS antes do momento normal, nas hipóteses e condições previstas pela legislação estadual. Não é sinônimo de DIFAL nem de substituição tributária.'],['Anexo do Simples','Tabela da LC 123/2006 que organiza faixas, alíquotas nominais e parcelas a deduzir para atividades do Simples. O enquadramento depende da atividade e de regras como o fator R, quando aplicável.'],['CPP','Contribuição Previdenciária Patronal. Sua forma de apuração varia conforme o regime, atividade e regra aplicável; no Simples, há situações em que fica fora do DAS.'],['CSRF','Retenções de contribuições sociais federais, expressão usada para retenções de PIS/Pasep, Cofins e CSLL em situações previstas.'],['DAS-MEI','Documento mensal de arrecadação do Microempreendedor Individual, gerado no PGMEI conforme atividade e competência.'],['DIFAL','Diferencial entre alíquota interestadual e interna do ICMS em hipóteses de operações interestaduais com consumidor final e outras situações previstas. A responsabilidade e o cálculo dependem da operação e da UF.'],['FCP','Fundo de Combate à Pobreza. Adicional estadual que pode incidir em produtos e operações definidos pela legislação local.'],['Fator R','Relação entre folha e receita usada para determinadas atividades do Simples Nacional.'],['GNRE','Guia Nacional de Recolhimento de Tributos Estaduais, usada em situações de recolhimento para outra UF; código, preenchimento e uso dependem da operação e da regra estadual.'],['ICMS-ST','ICMS recolhido por substituição tributária: a lei atribui a um participante da cadeia a responsabilidade pelo imposto de operações subsequentes ou antecedentes.'],['ISS próprio','ISS devido pelo próprio prestador do serviço ao município competente, calculado conforme o serviço, local de incidência, regime e legislação municipal. O prestador apura e recolhe o imposto; isso difere do ISS retido pelo tomador.'],['ISS retido','ISS descontado e recolhido pelo tomador ou responsável tributário, quando a lei atribui essa responsabilidade. A retenção não deve ser confundida com ISS próprio.'],['IRRF','Imposto de Renda Retido na Fonte. O responsável desconta e recolhe imposto em pagamentos sujeitos à retenção, conforme natureza, beneficiário e regras vigentes.'],['ITBI','Imposto municipal incidente sobre transmissão onerosa inter vivos de imóveis e direitos imobiliários nas hipóteses legais. Base e procedimento são definidos conforme legislação aplicável.'],['ITCMD','Imposto estadual sobre transmissão causa mortis e doação de bens ou direitos; alíquota, base, declaração e prazo dependem da lei estadual.'],['IPTU','Imposto municipal sobre propriedade predial e territorial urbana. Cadastro, valor venal, alíquotas e vencimento seguem a legislação municipal.'],['IPVA','Imposto estadual sobre a propriedade de veículos automotores. Alíquota, base, calendário e isenções dependem da UF e do veículo.'],['IOF','Imposto federal sobre operações de crédito, câmbio, seguro e títulos ou valores mobiliários, conforme modalidade e legislação vigente.'],['ITR','Imposto federal sobre propriedade territorial rural; a apuração considera características e utilização do imóvel, conforme regras vigentes.'],['II','Imposto de Importação incidente sobre a entrada de produto estrangeiro no território nacional, sujeito a classificação, origem, valor aduaneiro e regras aduaneiras.'],['NFS-e','Nota Fiscal de Serviço eletrônica, documento fiscal usado para registrar prestações de serviço conforme sistema nacional ou regras municipais aplicáveis.'],['RAT/FAP','RAT é a contribuição relacionada aos riscos ambientais do trabalho; FAP é fator que pode ajustar sua expressão conforme critérios oficiais. O cálculo exige dados da empresa e competência.'],['Repartição do Simples','Distribuição da alíquota efetiva entre os tributos que compõem o DAS. A parcela de cada tributo depende de anexo, faixa e regras aplicáveis; confira a informação oficial para a receita.'],['Salário-educação','Contribuição social destinada ao financiamento da educação básica, com incidência e exceções conforme legislação previdenciária e tributária.'],['Substituição tributária','Atribuição legal a contribuinte de recolher tributo devido em etapas subsequentes ou antecedentes da cadeia.'],['Tributos monofásicos','Tributos cuja incidência se concentra em etapa específica da cadeia para certos produtos. No Simples, receitas sujeitas a regras monofásicas podem exigir segregação no PGDAS-D.'],['CNPJ','Cadastro Nacional da Pessoa Jurídica, identificador cadastral das entidades perante a administração pública.'],['CST','Código de Situação Tributária, códigos usados para identificar a tributação de itens ou operações conforme documento e regime.'],['CSOSN','Código de Situação da Operação no Simples Nacional, usado em documentos fiscais por optantes do Simples nas hipóteses aplicáveis.'],['CEST','Código Especificador da Substituição Tributária, identificador usado para produtos sujeitos a regras de ICMS-ST quando aplicável.'],['DARE','Documento de Arrecadação de Receitas Estaduais; nome e uso variam conforme a UF.'],['DARF','Documento de Arrecadação de Receitas Federais, usado para recolhimentos federais conforme código e período.'],['DASN-SIMEI','Declaração Anual Simplificada para o Microempreendedor Individual, entregue pelo MEI com informações do ano-calendário.'],['DEFIS','Declaração de Informações Socioeconômicas e Fiscais das empresas do Simples Nacional, conforme obrigação aplicável.'],['EFD-Contribuições','Escrituração Fiscal Digital das contribuições sociais e previdenciárias, entregue por contribuintes obrigados conforme regras vigentes.'],['EFD ICMS/IPI','Escrituração Fiscal Digital de documentos, apurações e operações de ICMS e IPI dos contribuintes obrigados.'],['EFD-Reinf','Escrituração Fiscal Digital de Retenções e Outras Informações Fiscais, integrada ao eSocial e à DCTFWeb.'],['FGTS Digital','Sistema utilizado para gestão e recolhimento de valores de FGTS conforme eventos e regras aplicáveis.'],['MVA','Margem de Valor Agregado, percentual usado em algumas regras de cálculo do ICMS-ST para estimar valor de operações subsequentes. Consulte a regra do produto e da UF.'],['NF-e','Nota Fiscal eletrônica de mercadorias, modelo digital usado para documentar operações com produtos e outras hipóteses previstas.'],['PGDAS-D','Programa Gerador do Documento de Arrecadação do Simples Nacional — Declaratório, usado para informar receitas, apurar o valor mensal e gerar o DAS do Simples.'],['PER/DCOMP','Pedido Eletrônico de Restituição, Ressarcimento ou Reembolso e Declaração de Compensação, sistema da Receita para pedidos e compensações permitidos.'],['PVA','Programa Validador e Assinador utilizado em algumas escriturações digitais para validar, assinar e transmitir arquivos.'],['RPA','Recibo de Pagamento Autônomo, documento de pagamento a trabalhador autônomo; retenções e contribuições dependem do serviço e da situação.'],['SEFAZ','Secretaria da Fazenda ou órgão estadual equivalente, responsável por administrações tributárias estaduais.'],['Contribuição previdenciária do segurado','Parcela previdenciária descontada do trabalhador ou contribuinte individual, calculada conforme categoria, remuneração e limites vigentes.'],['IS','Imposto Seletivo previsto na reforma tributária do consumo, aplicável a bens e serviços definidos em lei. Confirme regulamentação e vigência.'],['ICMS próprio','ICMS apurado pelo contribuinte sobre suas operações próprias, em contraste com parcelas recolhidas por substituição tributária ou diferencial.'],['RAT','Risco Ambiental do Trabalho, contribuição previdenciária patronal vinculada ao grau de risco da atividade, conforme enquadramento vigente.'],['FAP','Fator Acidentário de Prevenção, índice que pode ajustar a contribuição relacionada aos riscos do trabalho conforme dados oficiais.']];
  const glossaryList=document.getElementById('glossaryList'),glossaryInput=document.getElementById('glossaryInput');function renderGlossary(){const t=glossaryInput.value.toLowerCase().trim();const arr=G.slice().sort((a,b)=>a[0].localeCompare(b[0],'pt-BR')).filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(t));glossaryList.innerHTML=arr.length?arr.map(x=>`<article class="term"><b>${esc(x[0])}</b><p>${esc(x[1])}</p></article>`).join(''):'<div class="empty">Nenhum termo encontrado.</div>'}glossaryInput.addEventListener('input',renderGlossary);renderGlossary();
