    function renderSimpleTable(id){const annex=simplesAnnexes.find(x=>x.id===id)||simplesAnnexes[0];const sharePct=n=>n===null?'—':`${n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}%`;simplesTabList.innerHTML=simplesAnnexes.map(x=>`<button type="button" role="tab" id="sn-tab-${x.id}" aria-selected="${x.id===annex.id}" aria-controls="simplesAnnexTable" data-annex="${x.id}">${x.name}</button>`).join('');simplesAnnexIntro.innerHTML=`<h3>${annex.name}</h3><p>${annex.activity}</p>`;simplesAnnexTable.innerHTML=`<div class="sn-table-block"><h4>Faixas, alíquota nominal e parcela a deduzir</h4><div class="table-scroll"><table class="sn-table"><thead><tr><th>Faixa pela RBT12</th><th>Alíquota nominal</th><th>Parcela a deduzir</th></tr></thead><tbody>${annex.rows.map((row,i)=>`<tr data-band="${i}"><td>${row[0]}</td><td>${row[2]}</td><td>${currencyBRL.format(row[3])}</td></tr>`).join('')}</tbody></table></div></div><div class="sn-table-block"><h4>Partilha dos tributos dentro do DAS (%)</h4><p class="fine">Os percentuais abaixo representam a composição do valor do DAS, conforme a faixa da RBT12.</p><div class="table-scroll"><table class="sn-table sn-share-table"><thead><tr><th>Faixa</th>${annex.taxes.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${annex.rows.map((row,i)=>`<tr data-band="${i}"><td>${row[0]}</td>${annex.split[i].map(value=>`<td>${sharePct(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${annex.splitNote?`<p class="fine" style="margin-top:10px">${annex.splitNote}</p>`:''}</div>`;simplesAnnexTable.setAttribute('aria-labelledby',`sn-tab-${annex.id}`);simplesAnnexTable.dataset.annex=annex.id;updateSimpleBracket()}
    function updateSimpleBracket(){if(!simplesRbtInput||!simplesBracketResult)return;const rbt=Number(simplesRbtInput.value),annex=simplesAnnexes.find(x=>x.id===simplesAnnexTable.dataset.annex)||simplesAnnexes[0];simplesAnnexTable.querySelectorAll('tbody tr').forEach(tr=>tr.classList.remove('current'));if(!rbt){simplesBracketResult.innerHTML='<p>Informe a RBT12 para localizar a faixa, alíquota nominal, parcela a deduzir e alíquota efetiva estimada.</p>';return}if(rbt<0){simplesBracketResult.innerHTML='<p>Informe uma receita igual ou maior que zero.</p>';return}if(rbt>4800000){simplesBracketResult.innerHTML='<p>RBT12 acima de R$ 4.800.000,00: este conjunto de faixas não cobre o caso. Verifique limite, sublimites e efeitos de eventual excesso com a legislação e o PGDAS-D.</p>';return}const index=annex.rows.findIndex(row=>rbt<=row[1]);if(index<0){simplesBracketResult.innerHTML='<p>Informe uma RBT12 maior que zero. Para início de atividade, confirme a regra proporcional aplicável no PGDAS-D.</p>';return}const row=annex.rows[index],nominal=Number(row[2].replace('%','').replace(',','.'))/100,pd=row[3],effective=rbt?Math.max(0,(rbt*nominal-pd)/rbt):0;simplesAnnexTable.querySelectorAll(`tbody tr[data-band="${index}"]`).forEach(tr=>tr.classList.add('current'));simplesBracketResult.innerHTML=`<div class="sn-result"><h4>${annex.name} · ${index+1}ª faixa</h4><p>${row[0]}</p><p>Alíquota nominal: <b>${row[2]}</b> · Parcela a deduzir: <b>${currencyBRL.format(pd)}</b></p><p>Alíquota efetiva estimada</p><p class="sn-rate">${percentBRL(effective)}</p></div>`}
    simplesTabList.addEventListener('click',e=>{const b=e.target.closest('[data-annex]');if(b)renderSimpleTable(b.dataset.annex)});simplesRbtInput.addEventListener('input',updateSimpleBracket);renderSimpleTable('I');

