    Object.entries(tabGuides).forEach(([id,items])=>{const section=document.getElementById(id);if(!section||section.querySelector('.tab-guide'))return;const box=document.createElement('aside');box.className='tab-guide';box.setAttribute('aria-label','Sobre esta aba');box.innerHTML=`<div><b>O que esta aba faz</b><p>${esc(items[0])}</p></div><div><b>Como ela pode ajudar</b><p>${esc(items[1])}</p></div>`;const head=section.querySelector('.section-head');if(id==='inicio'){section.querySelector('.hero-grid')?.insertAdjacentElement('beforeend',box)}else if(id==='reforma'){section.querySelector('.reform')?.insertAdjacentElement('beforebegin',box)}else if(head)head.insertAdjacentElement('afterend',box)});

