    const codeSearch=document.getElementById('codeSearch'),codeType=document.getElementById('codeType'),codeResults=document.getElementById('codeResults');
    function renderFiscalCodes(){if(!codeResults)return;const q=normalizeText(codeSearch.value),type=codeType.value,matches=fiscalCodeData.filter(x=>(!type||x.type===type)&&normalizeText(`${x.type} ${x.code} ${x.title} ${x.detail} ${x.tags}`).includes(q)),rows=q?matches.slice(0,80):matches.slice(0,6);codeResults.innerHTML=rows.length?`${q?'':`<p class="fine" style="grid-column:1/-1">Catálogo local com 589 CFOPs da planilha enviada, além dos exemplos de CST/CSOSN. Digite código ou descrição; a busca mostra até 80 resultados.</p>`}${rows.map(x=>`<article class="code-card"><span class="pill accent">${esc(x.type)}</span><h4>${esc(x.code)} · ${esc(x.title)}</h4><p>${esc(x.detail)}</p><p class="fine">Descrição resumida para conferência. Valide CFOP, CST/CSOSN, finalidade, regime, UF, documento e legislação da operação.</p></article>`).join('')}`:'<div class="empty">Nenhum código encontrado. Confira a grafia ou consulte a tabela oficial do CONFAZ.</div>'}
    codeSearch.addEventListener('input',renderFiscalCodes);codeType.addEventListener('change',renderFiscalCodes);renderFiscalCodes();
    // Consulta on-demand do JSON público do Classif; cache local diário para reduzir downloads repetidos.
    const ncmSearch=document.getElementById('ncmSearch'),ncmResults=document.getElementById('ncmResults'),ncmStatus=document.getElementById('ncmStatus');
    const ncmEndpoint='https://portalunico.siscomex.gov.br/classif/api/publico/nomenclatura/download/json?perfil=PUBLICO',ncmCacheKey='contaClara.ncm.vigente.v1';
    let ncmRows=null,ncmLoadPromise=null,ncmLastUpdate='';
    function getNcmRows(data){if(Array.isArray(data))return data;for(const key of ['nomenclaturas','ncm','listaNcm','listaNCM','Nomenclaturas','NCM'])if(Array.isArray(data?.[key]))return data[key];if(data&&typeof data==='object'){const array=Object.values(data).find(Array.isArray);if(array)return array}return []}
    // O JSON oficial usa nomes PascalCase (Codigo/Descricao); aliases cobrem variações futuras.
    function ncmCode(row){return String(row?.Codigo??row?.codigo??row?.CodigoNcm??row?.codigoNcm??row?.ncm??row?.NCM??'').replace(/\D/g,'')}
    function ncmDisplayCode(row){return String(row?.Codigo??row?.codigo??row?.CodigoNcm??row?.codigoNcm??row?.ncm??row?.NCM??'')}
    function ncmDescription(row){return String(row?.Descricao??row?.descricao??row?.DescricaoNcm??row?.descricaoNcm??row?.descricaoMercadoria??row?.Nomenclatura??'')}
    async function loadNcmCatalog(){if(ncmRows)return ncmRows;if(ncmLoadPromise)return ncmLoadPromise;ncmLoadPromise=(async()=>{ncmStatus.textContent='Carregando o catálogo oficial de NCM…';let source='';try{const cached=JSON.parse(localStorage.getItem(ncmCacheKey)||'null');if(cached&&Array.isArray(cached.rows)&&cached.savedAt&&Date.now()-cached.savedAt<24*60*60*1000){ncmRows=cached.rows;ncmLastUpdate=cached.lastUpdate||'';source='cache diário'}else{try{const response=await fetch(ncmEndpoint,{method:'GET',headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('Fonte oficial indisponível.');const data=await response.json();ncmRows=getNcmRows(data).filter(row=>ncmCode(row)&&ncmDescription(row));if(!ncmRows.length)throw new Error('Formato não reconhecido.');ncmLastUpdate=String(data?.Data_Ultima_Atualizacao_NCM??data?.dataUltimaAlteracao??data?.ultimaAlteracao??'');source='consulta direta ao Classif';try{localStorage.setItem(ncmCacheKey,JSON.stringify({savedAt:Date.now(),lastUpdate:ncmLastUpdate,rows:ncmRows}))}catch(_){/* Mantém a busca ativa na sessão se o navegador limitar o armazenamento. */}}catch(_){let stored=null;try{stored=JSON.parse(localStorage.getItem(ncmCacheKey)||'null')}catch(_){}
if(stored&&Array.isArray(stored.rows)&&stored.rows.length){ncmRows=stored.rows.filter(row=>ncmCode(row)&&ncmDescription(row));ncmLastUpdate=String(stored.lastUpdate||'');source='cópia local salva em '+new Date(stored.savedAt).toLocaleDateString('pt-BR')+' — CONFIRA VIGÊNCIA';}
if(!ncmRows?.length){const snapshot=JSON.parse(document.getElementById('ncmCatalogSnapshot').textContent);ncmRows=getNcmRows(snapshot).filter(row=>ncmCode(row)&&ncmDescription(row));ncmLastUpdate=String(snapshot?.Data_Ultima_Atualizacao_NCM||'');source='cópia incorporada ao site — CONFIRA VIGÊNCIA';}
if(!ncmRows.length)throw new Error('Catálogo incorporado inválido.');}}const updated=ncmLastUpdate?` · ${esc(ncmLastUpdate)}`:'';ncmStatus.textContent=`${ncmRows.length.toLocaleString('pt-BR')} posições NCM disponíveis (${source})${updated}. Consulte o Classif para confirmar vigência, notas e enquadramento.`;if(ncmSearch.value.trim())renderNcmResults();return ncmRows}catch(error){ncmRows=[];ncmStatus.innerHTML=`Não consegui abrir o catálogo agora. Consulte o <a href="https://portalunico.siscomex.gov.br/classif/#/nomenclatura/avancada?perfil=publico" target="_blank" rel="noopener">Classif oficial</a>.`;return ncmRows}finally{ncmLoadPromise=null}})();return ncmLoadPromise}
    function renderNcmResults(){const query=normalizeText(ncmSearch.value),digits=ncmSearch.value.replace(/\D/g,'');if(!query){ncmResults.innerHTML='';return}if(!ncmRows){ncmResults.innerHTML='<p class="fine">Carregando o catálogo oficial…</p>';return}if(!ncmRows.length){ncmResults.innerHTML='';return}const found=ncmRows.filter(row=>{const code=ncmCode(row),desc=normalizeText(ncmDescription(row));return (digits&&code.includes(digits))||desc.includes(query)}).slice(0,40);ncmResults.innerHTML=found.length?found.map(row=>`<article class="code-card"><span class="pill accent">Código NCM</span><h4>${esc(ncmDisplayCode(row))}</h4><p>${esc(ncmDescription(row))}</p><p class="fine">Consulte vigência, notas legais, atributos e enquadramento da mercadoria no Classif.</p></article>`).join(''):`<div class="empty">Nenhum NCM encontrado para essa busca. Tente outro trecho ou confira o histórico no Classif.</div>`}
