    // Casos didáticos pesquisáveis, com a resolução recolhida para estudo ativo.
    const practiceCases=[
      {topic:'Simples Nacional',question:'Uma empresa do Anexo I tem RBT12 de R$ 300.000 e receita de R$ 25.000 no mês. Como estimar o DAS?',answer:'Na 2ª faixa do Anexo I: (R$ 300.000 × 7,30% − R$ 5.940) ÷ R$ 300.000 = 5,32% de alíquota efetiva. Aplicando à receita mensal informada: R$ 25.000 × 5,32% = R$ 1.330. O PGDAS-D pode mudar o valor com segregações e particularidades.'},
      {topic:'Notas/XML',question:'A soma dos itens do XML confere, mas a chave ou o destinatário está diferente. O que fazer?',answer:'Não considere a conferência encerrada só porque o total fecha. Compare chave, emitente, destinatário, número, série, itens e totais com o XML autorizado e o registro da operação. A ferramenta do site não verifica autorização nem situação atual na SEFAZ.'},
      {topic:'Entrada fiscal',question:'A nota de entrada de material de uso e consumo gera crédito automaticamente?',answer:'Não. A finalidade e o regime importam, e a regra de crédito depende da legislação aplicável. Confira o documento, CFOP, CST/CSOSN, escrituração e regra da UF antes de aproveitar qualquer valor.'},
      {topic:'Aluguel e IRRF',question:'Uma empresa paga aluguel a uma pessoa física residente no Brasil. Qual é o primeiro cuidado?',answer:'Identifique beneficiário, valor e competência; verifique a base tributável e deduções permitidas, aplique a tabela mensal vigente e trate as informações da EFD-Reinf conforme orientação oficial. Não confunda com aluguel pago por PF, sujeito em regra ao Carnê-Leão pelo locador.'},
      {topic:'Fechamento mensal',question:'Qual conciliação simples evita que uma receita fique fora da apuração?',answer:'Compare notas emitidas, relatórios de venda, recebimentos bancários e registros contábeis por competência. Investigue diferenças antes de fechar o PGDAS-D ou a apuração do regime. Guarde a memória da conferência.'}
    ];
    const studySearch=document.getElementById('studySearch'),studyCases=document.getElementById('studyCases');
    function renderPracticeCases(){if(!studyCases)return;const q=normalizeText(studySearch.value),rows=practiceCases.filter(x=>normalizeText(`${x.topic} ${x.question} ${x.answer}`).includes(q));studyCases.innerHTML=rows.length?rows.map((x,i)=>`<details class="study-case"><summary>${esc(x.topic)} · ${esc(x.question)}</summary><p>${esc(x.answer)}</p></details>`).join(''):'<div class="empty">Nenhum caso de estudo encontrado.</div>'}
