    const commonCloseTasks=[['docs','Reunir notas fiscais de entrada e saída'],['xml','Conferir XMLs, cancelamentos, devoluções e duplicidades'],['bank','Conciliar extratos, recebimentos e registros contábeis'],['revenue','Conferir faturamento, competência e segregação das receitas'],['codes','Revisar cadastros fiscais, CFOP, NCM e CST/CSOSN'],['archive','Arquivar memória de cálculo, documentos e comprovantes']];
