    let closeStore={};try{closeStore=JSON.parse(localStorage.getItem('cc_close_monthly')||'{}')}catch(e){}
    const closeToday=new Date();closeEls.closePeriod.value=`${closeToday.getFullYear()}-${String(closeToday.getMonth()+1).padStart(2,'0')}`;
    let activeCloseKey='';function closeKey(){const name=normalizeText(closeEls.closeCompany.value)||'minha empresa';return `${closeEls.closePeriod.value||'sem-competencia'}::${name}`}
    function closeTaskCatalog(){return [...commonCloseTasks,...(regimeCloseTasks[closeEls.closeRegime.value]||[]),...(closeEls.closeEmployees.value==='sim'?staffCloseTasks:[])].map(([id,title])=>({id,title}))}
    function readCloseForm(key=activeCloseKey||closeKey()){return {company:closeEls.closeCompany.value.trim(),period:closeEls.closePeriod.value,regime:closeEls.closeRegime.value,uf:closeEls.closeUF.value,employees:closeEls.closeEmployees.value==='sim',revenue:Math.max(0,+closeEls.closeRevenue.value||0),payroll:Math.max(0,+closeEls.closePayroll.value||0),taxes:Math.max(0,+closeEls.closeTaxes.value||0),tasks:closeStore[key]?.tasks||{}}}
