    function renderCloseProgress(){const tasks=closeTaskCatalog(),data=closeStore[activeCloseKey||closeKey()]||{},done=tasks.filter(t=>data.tasks?.[t.id]?.done).length,pct=tasks.length?Math.round(done/tasks.length*100):0;closeProgress.max=100;closeProgress.value=pct;closeProgressLabel.textContent=`${done} de ${tasks.length} tarefas concluídas`;closeProgressPercent.textContent=`${pct}%`}
    function renderCloseTasks(){const data=closeStore[activeCloseKey||closeKey()]||{tasks:{}};closeTasks.innerHTML=closeTaskCatalog().map(t=>{const saved=data.tasks?.[t.id]||{};return `<article class="close-task"><label><input type="checkbox" class="close-done" data-task="${t.id}" ${saved.done?'checked':''}><span>${esc(t.title)}</span></label><div class="close-task-fields"><label>Prazo interno (opcional)<input class="field close-due" data-task="${t.id}" type="date" value="${esc(saved.due||'')}"></label><label>Observação interna<textarea class="field close-note" data-task="${t.id}" rows="2" maxlength="300" placeholder="Sem dados sensíveis">${esc(saved.note||'')}</textarea></label></div></article>`}).join('');renderCloseProgress()}
    function loadCloseEntry(){activeCloseKey=closeKey();const data=closeStore[activeCloseKey]||{};closeEls.closeRevenue.value=data.revenue??'';closeEls.closePayroll.value=data.payroll??'';closeEls.closeTaxes.value=data.taxes??'';closeEls.closeRegime.value=data.regime||'Simples Nacional';closeEls.closeUF.value=data.uf||'GO';closeEls.closeEmployees.value=data.employees?'sim':'nao';renderCloseTasks();closeSavedStatus.textContent='Competência carregada. Dados salvos localmente neste navegador.'}
