    closeTasks.addEventListener('input',e=>{if(!e.target.classList.contains('close-note'))return;const id=e.target.dataset.task,key=activeCloseKey||closeKey(),entry=closeStore[key]||{tasks:{}};entry.tasks=entry.tasks||{};entry.tasks[id]=entry.tasks[id]||{};entry.tasks[id].note=e.target.value;closeStore[key]=entry;try{localStorage.setItem('cc_close_monthly',JSON.stringify(closeStore))}catch(err){}});
