    const pageSections=[...document.querySelectorAll('main > section')],mainNav=document.getElementById('mainNav');
    function showPage(id,updateUrl=true){let target=document.getElementById(id);let section=target?.closest('section');if(!section||!pageSections.includes(section))section=document.getElementById('inicio');const isHome=section.id==='inicio'||section.id==='assuntos';pageSections.forEach(x=>{x.hidden=isHome?!(x.id==='inicio'||x.id==='assuntos'):x!==section});const activeId=isHome?'inicio':section.id;mainNav.querySelectorAll('a[href^="#"]').forEach(a=>{const active=a.getAttribute('href')==='#'+activeId;a.setAttribute('aria-current',active?'page':'false')});if(updateUrl)history.replaceState(null,'','#'+activeId);const menu=document.getElementById('mainNav');menu.classList.remove('show');document.getElementById('menuToggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'smooth'});if(id!==activeId&&target&&section.contains(target))setTimeout(()=>target.scrollIntoView({block:'start',behavior:'smooth'}),80)}
